insert into public.panda_records(kind,id,data) values('recipes','recipe_05','{"id":"recipe_05","name":"Avocado egg toast","name_ar":"توست الأفوكادو والبيض","category":"Breakfast","minutes":15,"wait_minutes":0,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"bread","name":"Wholegrain bread","name_ar":"خبز حبوب كاملة","protein":10,"carbs":40,"fat":4,"fiber":7,"allergens":"Wheat, Gluten","unit":"g","quantity":80},{"id":"avocado","name":"Avocado · flesh only","name_ar":"لب الأفوكادو","protein":2,"carbs":1.8,"fat":15,"fiber":6.7,"allergens":"","unit":"g","quantity":60},{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":100},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":10}],"steps":["Hard-boil the eggs, then peel and halve. Toast the bread.","Mash the avocado with the lemon juice and spread over the toast.","Add the eggs and tomatoes. Use black pepper to taste."],"steps_ar":["اسلق البيض حتى يتماسك ثم قشره واقطعه وحمص الخبز.","اهرس الأفوكادو مع عصير الليمون ووزعه على الخبز.","أضف البيض والطماطم والفلفل الأسود حسب الرغبة."],"tags":["Vegetarian"],"allergens":["Egg","Gluten","Wheat"],"image":"assets/recipes/05.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","