insert into public.panda_records(kind,id,data) values('recipes','recipe_18','{"id":"recipe_18","name":"Turkey meatballs with wholewheat pasta","name_ar":"كرات الديك الرومي بالمكرونة الكاملة","category":"Main meals","minutes":35,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"turkey","name":"Turkey mince · raw, lean","name_ar":"ديك رومي مفروم نيئ قليل الدهن","protein":22,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":15},{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":25},{"id":"pasta","name":"Wholewheat pasta · dry","name_ar":"مكرونة قمح كامل جافة","protein":13,"carbs":63,"fat":2.5,"fiber":8,"allergens":"Wheat, Gluten","unit":"g","quantity":65},{"id":"passata","name":"Passata · plain tomato","name_ar":"طماطم مهروسة سادة","protein":1.5,"carbs":4,"fat":0.3,"fiber":1.5,"allergens":"","unit":"g","quantity":180},{"id":"onion","name":"Onion · raw","name_ar":"بصل نيئ","protein":1.1,"carbs":7.5,"fat":0.1,"fiber":1.7,"allergens":"","unit":"g","quantity":40},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"garlic","name":"Garlic · raw","name_ar":"ثوم نيئ","protein":6,"carbs":28,"fat":0.5,"fiber":2,"allergens":"","unit":"g","quantity":5}],"steps":["Mix turkey, finely ground oats and egg; form small meatballs. Heat the oil and brown them gently.","Add chopped onion, garlic and passata. Cover and simmer until meatballs reach 74°C throughout.","Cook and drain the pasta; serve with the meatballs and sauce."],"steps_ar":["اخلط الديك الرومي والشوفان المطحون والبيض وشكل كرات صغيرة وحمرها برفق في الزيت.","أضف البصل والثوم والطماطم وغطها حتى تبلغ حرارة الكرات ٧٤°م.","اطه المكرونة وصفها وقدمها مع الكرات والصلصة."],"tags":["Meal prep"],"allergens":["Egg","Gluten","Wheat"],"image":"assets/recipes/18.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_19','{"id":"recipe_19","name":"Chicken and red lentil curry","name_ar":"كاري الدجاج والعدس الأحمر","category":"Main meals","minutes":35,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"chicken","name":"Chicken breast · raw, skinless","name_ar":"صدر دجاج نيئ دون الجلد","protein":23,"carbs":0,"fat":2,"fiber":0,"allergens":"","unit":"g","quantity":150},{"id":"lentildry","name":"Red lentils · dry","name_ar":"عدس أحمر جاف","protein":24,"carbs":50,"fat":1.5,"fiber":11,"allergens":"","unit":"g","quantity":45},{"id":"passata","name":"Passata · plain tomato","name_ar":"طماطم مهروسة سادة","protein":1.5,"carbs":4,"fat":0.3,"fiber":1.5,"allergens":"","unit":"g","quantity":120},{"id":"coconut","name":"Coconut milk · light","name_ar":"حليب جوز الهند الخفيف","protein":0.8,"carbs":2,"fat":7,"fiber":0,"allergens":"","unit":"g","quantity":80},{"id":"spinach","name":"Spinach · raw","name_ar":"سبانخ نيئة","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"allergens":"","unit":"g","quantity":60},{"id":"onion","name":"Onion · raw","name_ar":"بصل نيئ","protein":1.1,"carbs":7.5,"fat":0.1,"fiber":1.7,"allergens":"","unit":"g","quantity":50},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Soften onion in oil, add chicken cubes and curry spices, and stir for 3 minutes.","Add rinsed lentils, passata, coconut milk and 150 g water. Simmer 20 minutes, adding more water if needed.","Check the lentils are tender and chicken is at least 74°C; stir in spinach to wilt."],"steps_ar":["لين البصل بالزيت وأضف مكعبات الدجاج وبهارات الكار