insert into public.panda_records(kind,id,data) values('recipes','recipe_20','{"id":"recipe_20","name":"Beef and broccoli rice bowl","name_ar":"بول الأرز باللحم والبروكلي","category":"Main meals","minutes":25,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"beef","name":"Beef mince · raw, 5% fat","name_ar":"لحم بقري مفروم نيئ ٥٪ دهون","protein":21,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":160},{"id":"broccoli","name":"Broccoli · raw","name_ar":"بروكلي نيئ","protein":2.8,"carbs":4,"fat":0.4,"fiber":2.6,"allergens":"","unit":"g","quantity":180},{"id":"rice","name":"Basmati rice · dry","name_ar":"أرز بسمتي جاف","protein":7.5,"carbs":78,"fat":0.7,"fiber":1.2,"allergens":"","unit":"g","quantity":65},{"id":"soy","name":"Soy sauce · reduced salt","name_ar":"صلصة صويا قليلة الملح","protein":8,"carbs":5,"fat":0.5,"fiber":0,"allergens":"Soy, Wheat","unit":"g","quantity":15},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"garlic","name":"Garlic · raw","name_ar":"ثوم نيئ","protein":6,"carbs":28,"fat":0.5,"fiber":2,"allergens":"","unit":"g","quantity":5}],"steps":["Cook the rice and cut the broccoli into small florets.","Brown the mince with oil and garlic until it reaches 71°C. Add broccoli and a splash of water; cover briefly.","Uncover, add soy sauce and stir until broccoli is tender-crisp. Serve over rice."],"steps_ar":["اطه الأرز وقطع البروكلي إلى زهرات صغيرة.","حمر اللحم بالزيت والثوم حتى يبلغ ٧١°م ثم أضف البروكلي وقليلاً من الماء وغطه لفترة قصيرة.","أضف الصويا وقلب حتى يلين البروكلي مع بقائه متماسكاً وقدمه فوق الأرز."],"tags":["Quick"],"allergens":["Soy","Wheat"],"image":"assets/recipes/20.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
