insert into public.panda_records(kind,id,data) values('recipes','recipe_33','{"id":"recipe_33","name":"Apple peanut yogurt bowl","name_ar":"بول الزبادي والتفاح والفول السوداني","category":"Snacks","minutes":5,"wait_minutes":0,"servings":1,"summary":"An easy extra to fit around your assigned meals.","summary_ar":"خيار سهل يناسب جدول وجباتك المحدد.","ingredients":[{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":200},{"id":"apple","name":"Apple · core removed","name_ar":"تفاح دون البذور","protein":0.3,"carbs":11.5,"fat":0.2,"fiber":2.4,"allergens":"","unit":"g","quantity":150},{"id":"peanut","name":"Peanut butter · unsweetened","name_ar":"زبدة فول سوداني دون سكر","protein":25,"carbs":12,"fat":50,"fiber":6,"allergens":"Peanuts","unit":"g","quantity":15},{"id":"cinnamon","name":"Cinnamon · ground","name_ar":"قرفة مطحونة","protein":4,"carbs":28,"fat":1,"fiber":53,"allergens":"","unit":"g","quantity":1}],"steps":["Core and slice the apple. Spoon yogurt into a bowl.","Thin peanut butter with a little warm water if needed, then drizzle over the yogurt.","Add apple slices and cinnamon."],"steps_ar":["أزل بذور التفاح وقطعه وضع الزبادي في وعاء.","خفف زبدة الفول السوداني بقليل من الماء الدافئ عند الحاجة ووزعها على الزبادي.","أضف شرائح التفاح والقرفة."],"tags":["Vegetarian","No-cook"],"allergens":["Milk","Peanuts"],"image":"assets/recipes/33.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_34','{"id":"recipe_34","name":"Tuna cucumber rice cakes","name_ar":"كعك الأرز بالتونة والخيار","category":"Snacks","minutes":10,"wait_minutes":0,"servings":1,"summary":"An easy extra to fit around your assigned meals.","summary_ar":"خيار سهل يناسب جدول وجباتك المحدد.","ingredients":[{"id":"tuna","name":"Tuna in water · drained","name_ar":"تونة بالماء مصفاة","protein":25,"carbs":0,"fat":1,"fiber":0,"allergens":"Fish","unit":"g","quantity":120},{"id":"ricecake","name":"Plain rice cakes","name_ar":"كعك أرز سادة","protein":8,"carbs":80,"fat":3,"fiber":3,"allergens":"","unit":"g","quantity":30},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":40},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":80},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":10}],"steps":["Drain tuna thoroughly, then mix with yogurt and lemon juice.","Slice cucumber thinly and arrange on the rice cakes.","Top with tuna and eat soon after assembling to keep the rice cakes crisp."],"steps_ar":["صف التونة جيداً واخلطها بالزبادي وعصير الليمون.","قطع الخيار رفيعاً ورتبه على كعك الأرز.","أضف التونة وتناولها بعد التحضير للحفاظ على القرمشة."],"tags":["No-cook"],"allergens":["Fish","Milk"],"image":"assets/recipes/34.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"20