insert into public.panda_records(kind,id,data) values('recipes','recipe_35','{"id":"recipe_35","name":"Egg and potato salad","name_ar":"سلطة البيض والبطاطس","category":"Main meals","minutes":30,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"egg","name":"Whole egg · shell removed","name_ar":"بيض كامل دون القشرة","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"allergens":"Egg","unit":"g","quantity":100},{"id":"potato","name":"Potato · raw","name_ar":"بطاطس نيئة","protein":2,"carbs":16,"fat":0.1,"fiber":2.2,"allergens":"","unit":"g","quantity":250},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":100},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"parsley","name":"Parsley · fresh","name_ar":"بقدونس طازج","protein":3,"carbs":3,"fat":0.8,"fiber":3.3,"allergens":"","unit":"g","quantity":10},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":5},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":15}],"steps":["Boil the eggs until firm. Cut potatoes into even pieces and simmer separately until tender, then drain.","Cool briefly, peel eggs and chop. Mix yogurt, lemon, oil and parsley.","Fold potatoes, eggs and cucumber into the dressing. Serve or chill promptly."],"steps_ar":["اسلق البيض حتى يتماسك وقطع البطاطس واطهها في قدر منفصل حتى تلين ثم صفها.","بردها قليلاً وقشر البيض وقطعه واخلط الزبادي والليمون والزيت والبقدونس.","قلب البطاطس والبيض والخيار مع الصلصة وقدمها أو بردها سريعاً."],"tags":["Vegetarian","Meal prep"],"allergens":["Egg","Milk"],"image":"assets/recipes/35.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
