insert into public.panda_records(kind,id,data) values('recipes','recipe_38','{"id":"recipe_38","name":"Turkey burger and potato wedges","name_ar":"برغر الديك الرومي وشرائح البطاطس","category":"Main meals","minutes":40,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"turkey","name":"Turkey mince · raw, lean","name_ar":"ديك رومي مفروم نيئ قليل الدهن","protein":22,"carbs":0,"fat":5,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"bread","name":"Wholegrain bread","name_ar":"خبز حبوب كاملة","protein":10,"carbs":40,"fat":4,"fiber":7,"allergens":"Wheat, Gluten","unit":"g","quantity":70},{"id":"potato","name":"Potato · raw","name_ar":"بطاطس نيئة","protein":2,"carbs":16,"fat":0.1,"fiber":2.2,"allergens":"","unit":"g","quantity":180},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":80},{"id":"spinach","name":"Spinach · raw","name_ar":"سبانخ نيئة","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"allergens":"","unit":"g","quantity":20},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":40},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":7},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Heat the oven to 200°C. Toss potato wedges in half the oil and roast 30–35 minutes, turning once.","Shape turkey and spices into a patty. Pan-cook with remaining oil until its centre reaches 74°C.","Serve between two wholegrain bread slices with yogurt, tomato and spinach, with wedges alongside."],"steps_ar":["سخن الفرن إلى ٢٠٠°م واخلط شرائح البطاطس بنصف الزيت واشوها ٣٠–٣٥ دقيقة مع التقليب.","شكل الديك الرومي والبهارات قرصاً واطهه ببقية الزيت حتى يبلغ ٧٤°م.","قدمه بين شريحتي خبز كامل مع الزبادي والطماطم والسبانخ والبطاطس بجانبه."],"tags":["Meal prep"],"allergens":["Check blend","Gluten","Milk","Wheat"],"image":"assets/recipes/38.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_39','{"id":"recipe_39","name":"Chicken shawarma rice bowl","name_ar":"بول شاورما الدجاج والأرز","category":"Main meals","minutes":30,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"chicken","name":"Chicken breast · raw, skinless","name_ar":"صدر دجاج نيئ دون الجلد","protein":23,"carbs":0,"fat":2,"fiber":0,"allergens":"","unit":"g","quantity":170},{"id":"rice","name":"Basmati rice · dry","name_ar":"أرز بسمتي جاف","protein":7.5,"carbs":78,"fat":0.7,"fiber":1.2,"allergens":"","unit":"g","quantity":60},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"cucumber","name":"Cucumber · raw","name_ar":"خيار نيئ","protein":0.7,"carbs":2,"fat":0.1,"fiber":0.5,"allergens":"","unit":"g","quantity":100},{"id":"tomato","name":"Tomatoes · raw","name_ar":"طماطم نيئة","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"allergens":"","unit":"g","quantity":100},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","unit":"g","quantity":6},{"id":"lemon","name":"Lemon juice","name_ar":"عصير ليمون","protein":0.4,"carbs":2.5,"fat":0.2,"fiber":0.3,"allergens":"","unit":"g","quantity":15},{"id":"garlic","name":"Garlic · raw","name_ar":"ثوم نيئ","protein":6,"carbs":28,"fat":0.5,"fiber":2,"allergens":"","unit":"g","quantity":5},{"id":"spice","name":"Ground spice mix · unsalted","name_ar":"بهارات مطحونة دون ملح","protein":10,"carbs":35,"fat":10,"fiber":20,"allergens":"Check blend","unit":"g","quantity":3}],"steps":["Coat thin chicken strips in half the yogurt, spices, garlic and oil. Start cooking the rice.","Pan-cook chicken until browned and its centre reaches 74°C. Mix remaining yogurt with lemon for the sauce.","Serve chicken over rice with chopped cucumber, tomato and the yogurt sauce."],"steps_ar":["غط شرائح الدجاج بنصف الزبادي والبهارات والثوم والزيت وابدأ طهي الأرز.","اطه الدجاج حتى يحمر وتبلغ حرارته الداخلية ٧٤°م واخلط بقية الزبادي بالليمون للصلصة.","قدم الدجاج فوق الأرز مع الخيار والطماطم المقطعة وصلصة الزبادي."],"tags":["Meal prep"],"allergens":["Check blend","Milk"],"image":"assets/recipes/39.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('recipes','recipe_40','{"id":"recipe_40","name":"Date walnut overnight oats","name_ar":"شوفان ليلي بالتمر والجوز","category":"Breakfast","minutes":5,"wait_minutes":240,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":50},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":170},{"id":"milk","name":"Milk · 1.5% fat","name_ar":"حليب قليل الدسم","protein":3.5,"carbs":5,"fat":1.5,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"date","name":"Dates · pitted","name_ar":"تمر دون النوى","protein":2,"carbs":68,"fat":0.2,"fiber":7,"allergens":"","unit":"g","quantity":25},{"id":"walnut","name":"Walnuts","name_ar":"جوز","protein":15,"carbs":7,"fat":65,"fiber":6.7,"allergens":"Tree nuts","unit":"g","quantity":15},{"id":"cinnamon","name":"Cinnamon · ground","name_ar":"قرفة مطحونة","protein":4,"carbs":28,"fat":1,"fiber":53,"allergens":"","unit":"g","quantity":1}],"steps":["Pit and finely chop the dates. Stir oats, yogurt, milk, dates and cinnamon together.","Cover and refrigerate for at least 4 hours or overnight.","Stir before serving and finish with chopped walnuts."],"steps_ar":["انزع نوى التمر وافرمه واخلط الشوفان والزبادي والحليب والتمر والقرفة.","غطه وبرده ٤ ساعات على الأقل أو طوال الليل.","قلبه قبل التقديم وأضف الجوز المفروم."],"tags":["Vegetarian","No-cook"],"allergens":["Gluten","Milk","Tree nuts"],"image":"assets/recipes/40.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','welcome','{"id":"welcome","category":"Getting started","title":"Your portal, your plan","summary":"Know where to find your plans and how to keep your coach informed.","image":"assets/education/education-welcome.webp","sections":[["Your home base","Your dashboard brings together the plan assigned to you, your nutrition strategy and your next check-in. Open the reference you need, then return when you have feedback to share."],["Before you begin","Check your profile, goals, availability, food preferences and any limitations with your coach. Read the coaching guidelines and the current version of each assigned plan."],["Keep the feedback useful","A short specific note about training, meals or recovery helps your coach make the next adjustment. You do not need to enter every set during your training."],["Build your first-week routine","Start by choosing realistic places in your week for the sessions your coach has assigned. Review the whole training day before you arrive at the gym: the exercise order, the equipment you need and any substitutions already agreed. Then open Nutrition and select the day variant that applies. A recipe is a preparation guide; it becomes part of your daily plan when your coach places it there. Simply opening a recipe does not change your calorie target.\n\nKeep the portal useful and lightweight. It is a reference for preparation and reflection, so you can put your phone away when you train. A short review after a session is often enough to remember the questions you want to raise."],["Make the next action obvious","Use Dashboard for your current priorities, Training for the prescription, Recipes for cooking instructions and Check-in for feedback. The Explore menu brings every available resource together. Your package determines which areas you can open. If you cannot find an expected plan, ask your coach to confirm both the assignment and publication status.\n\nBefore your first review, check that your profile reflects your current schedule and food preferences. These details make the coaching conversation more specific than a simple “good week” or “bad week”."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"welcome","category":"Getting started","title":"Your portal, your plan","summary":"Know where to find your plans and how to keep your coach informed.","image":"assets/education/education-welcome.webp","sections":[["Your home base","Your dashboard brings together the plan assigned to you, your nutrition strategy and your next check-in. Open the reference you need, then return when you have feedback to share."],["Before you begin","Check your profile, goals, availability, food preferences and any limitations with your coach. Read the coaching guidelines and the current version of each assigned plan."],["Keep the feedback useful","A short specific note about training, meals or recovery helps your coach make the next adjustment. You do not need to enter every set during your training."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','plans','{"id":"plans","category":"Training","title":"Read your training plan","summary":"Understand the difference between a prescription and feedback.","image":"assets/education/education-plans.webp","sections":[["Read the full day","Review the exercise order, sets, repetition range, written rest guidance and coach notes. Any sample working load is a plan example, not a required starting weight."],["Exercise references","Open the linked exercise to see its muscle targets, equipment and catalogue cue. Each photograph illustrates its linked exercise. Read the written cue and ask your coach to confirm your setup."],["Changes and questions","Tell your coach about unavailable equipment, discomfort or a schedule change. The coach can publish a new plan version while your earlier check-ins remain in the history."],["Understand effort, repetitions and rest","A prescription such as 3 × 8–12 means three working sets, with each set aiming for the stated repetition range. Warm-up sets are separate unless your coach says otherwise. The working load should allow the intended technique and range of motion. Completing a number by shortening the movement or losing control does not make the set equivalent.\n\nRest is part of the prescription. It allows the next set to be performed with the required quality. If a busy gym interrupts the order or changes your rest substantially, keep a short note rather than treating the session as identical to the previous week."],["Progress without guessing","Agree with your coach how progression will be judged. One example is to build repetitions within a range before increasing load, while keeping technique, exercise setup and rest comparable. This is an example of a progression method, not an automatic rule that overrides your programme.\n\nUseful feedback identifies the exercise, what you completed and what limited you. “Last two repetitions became rushed” gives your coach more to work with than “too hard”. Report pain, unusual symptoms or a movement you cannot control, and stop the affected exercise rather than forcing a target."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"plans","category":"Training","title":"Read your training plan","summary":"Understand the difference between a prescription and feedback.","image":"assets/education/education-plans.webp","sections":[["Read the full day","Review the exercise order, sets, repetition range, written rest guidance and coach notes. Any sample working load is a plan example, not a required starting weight."],["Exercise references","Open the linked exercise to see its muscle targets, equipment and catalogue cue. Each photograph illustrates its linked exercise. Read the written cue and ask your coach to confirm your setup."],["Changes and questions","Tell your coach about unavailable equipment, discomfort or a schedule change. The coach can publish a new plan version while your earlier check-ins remain in the history."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','nutrition','{"id":"nutrition","category":"Nutrition","title":"Make your meal plan practical","summary":"Portions, reference units and preparation all matter.","image":"assets/education/education-nutrition.webp","sections":[["Understand the reference","Some foods are listed per 100 grams, others per egg, packet or tablespoon. The quantity in your meal uses the same unit. Rice labelled uncooked is weighed before cooking."],["Plan total versus target","The planned meal total is calculated from the ingredients. The coach target is shown separately. A difference is visible so the plan can be adjusted rather than hidden."],["Bring practical feedback","Tell your coach which meals suit your routine, which ingredients are unavailable and what you would like to swap. Check allergies and preferences before following a new plan."],["Read a meal from ingredients upward","The ingredient amount and preparation state are the starting point. A cooked weight includes absorbed or lost water; a raw or dry weight does not represent the same portion after cooking. Oils, nut butters, sauces and toppings also contribute nutrients. Use the measured amounts in the plan instead of copying the visual size of the photograph.\n\nThe recipe panel shows estimated calories, protein, carbohydrate, fat and fibre for the displayed number of servings. If a recipe makes four servings, the ingredient editor describes the whole batch and the client view scales it to the assigned portion. Brand differences and cooking losses mean these are planning estimates."],["Make consistency practical","Choose a shopping and preparation routine you can repeat. Prepare a few ingredients in advance, keep convenient options available and tell your coach when a meal repeatedly conflicts with work or family commitments. The most elaborate meal is not automatically the most useful one.\n\nBefore a new assignment, check the ingredient list and allergen notes against the actual product label and your personal requirements. Your coach can change the recipe, portion or meal timing. Do not add an extra assigned recipe on top of the full plan unless that is what has been agreed."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"nutrition","category":"Nutrition","title":"Make your meal plan practical","summary":"Portions, reference units and preparation all matter.","image":"assets/education/education-nutrition.webp","sections":[["Understand the reference","Some foods are listed per 100 grams, others per egg, packet or tablespoon. The quantity in your meal uses the same unit. Rice labelled uncooked is weighed before cooking."],["Plan total versus target","The planned meal total is calculated from the ingredients. The coach target is shown separately. A difference is visible so the plan can be adjusted rather than hidden."],["Bring practical feedback","Tell your coach which meals suit your routine, which ingredients are unavailable and what you would like to swap. Check allergies and preferences before following a new plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','swaps','{"id":"swaps","category":"Nutrition","title":"Food swaps with context","summary":"Matching one nutrient does not make two foods identical.","image":"assets/education/education-swaps.webp","sections":[["Use a confirmed swap","The swap guide matches a chosen nutrient using the reference portions. Protein-equivalent servings can have different calories, fats and food volumes."],["Keep preparation consistent","Use the preparation state and portion unit written in the plan. A dry rice serving and a cooked rice serving cannot be exchanged gram for gram."],["Ask for an alternative","Report availability, preferences or digestion issues in your check-in. Your coach decides whether to change the food, portion or full meal."],["Compare the whole meal","A protein-based swap answers one specific question: what portion provides a similar amount of protein? It does not guarantee equal energy, carbohydrate, fat, fibre, sodium or fullness. For example, changing between a lean protein and a fattier protein may require a separate adjustment to the oil or other ingredients in the meal.\n\nLook at the resulting meal totals and the daily plan rather than one green number. Recipe assignments preserve the version chosen by your coach, so a newly edited template does not silently change a previously assigned portion."],["Describe the replacement you need","A helpful request includes the original ingredient, the reason for changing it and what is realistically available. Mention whether the issue is taste, cost, cooking time, availability or tolerance. Give the coach a product label or clear ingredient description if the replacement is packaged.\n\nOnce the alternative is agreed, use the preparation state and portion that belong to that alternative. A similar-looking plate is not a reliable measurement. Keep one consistent method so the next check-in reflects what you actually followed."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"swaps","category":"Nutrition","title":"Food swaps with context","summary":"Matching one nutrient does not make two foods identical.","image":"assets/education/education-swaps.webp","sections":[["Use a confirmed swap","The swap guide matches a chosen nutrient using the reference portions. Protein-equivalent servings can have different calories, fats and food volumes."],["Keep preparation consistent","Use the preparation state and portion unit written in the plan. A dry rice serving and a cooked rice serving cannot be exchanged gram for gram."],["Ask for an alternative","Report availability, preferences or digestion issues in your check-in. Your coach decides whether to change the food, portion or full meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','checkin','{"id":"checkin","category":"Coaching","title":"A useful weekly check-in","summary":"Give your coach the context behind the numbers.","image":"assets/education/education-checkin.webp","sections":[["Review the week","Consider training frequency, nutrition adherence, energy, sleep, hunger and digestion. An honest incomplete week is more useful than an invented perfect week."],["Describe one example","Say what made a meal difficult or why a training day moved. Include changes to schedule, travel or equipment where relevant."],["Submit and review","Save a draft if you need more time. Once submitted, your coach can review the entry and leave feedback alongside your original answers."],["Separate observations from interpretation","Start with facts you can describe: sessions completed, meals that were difficult to prepare, nights with less sleep and any changes in routine. Then describe how the week felt. A scale increase is an observation; “the plan has stopped working” is an interpretation that needs more context.\n\nUse the same rating scale each week. A recovery score should mean roughly the same thing to you across reviews. If you change how you interpret a rating, explain it in the notes. Consistent reporting makes patterns easier for you and your coach to discuss."],["Write feedback your coach can act on","Use a simple structure: what happened, why it mattered and what you need next. For example: “I completed three of four sessions. Thursday moved because of work, and I could not fit both lower-body days. Can we review next week’s schedule?”\n\nRead the coach response before changing several things at once. Agree on the next adjustment and keep the rest of the routine reasonably stable. A check-in is a conversation about the next useful step, not a judgement of your character or commitment."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"checkin","category":"Coaching","title":"A useful weekly check-in","summary":"Give your coach the context behind the numbers.","image":"assets/education/education-checkin.webp","sections":[["Review the week","Consider training frequency, nutrition adherence, energy, sleep, hunger and digestion. An honest incomplete week is more useful than an invented perfect week."],["Describe one example","Say what made a meal difficult or why a training day moved. Include changes to schedule, travel or equipment where relevant."],["Submit and review","Save a draft if you need more time. Once submitted, your coach can review the entry and leave feedback alongside your original answers."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','measure','{"id":"measure","category":"Progress","title":"Measure consistently","summary":"Make comparisons meaningful by keeping the method stable.","image":"assets/education/education-measure.webp","sections":[["Record the context","Use the same unit and note the date. Where possible, keep the measurement conditions consistent and tell your coach when a method changes."],["Missing is not zero","Leave an unknown measurement blank. The portal keeps missing values separate from real readings and plots only values that were entered."],["Photographs","Use comparable pose, distance, lighting and clothing for private progress references. In this frontend demo, uploaded images remain in this browser’s local data."],["Understand what a trend can tell you","A measurement is a snapshot, and its meaning depends on the method. Body weight can vary with hydration, food in the digestive system and the timing of the measurement. A tape measure can change with placement and tension. Keep these conditions as similar as reasonably possible before comparing results.\n\nUse the chart to review the direction over comparable dates rather than reacting to one point. A missing entry remains missing; it is not evidence that your weight or circumference reached zero. If the method changed, record a note so your coach can interpret the series."],["Make photographs comparable","Choose a repeatable camera position, distance, light and pose. Keep your full outline inside the frame, avoid a wide-angle close-up and use similar clothing. Front, side and back views are more useful when taken with the same setup on each date.\n\nPictures are optional coaching context, not a requirement to look a particular way on every day. Review visual changes alongside measurements, performance and how the routine feels. If you replace or remove a photo, export the data you want to keep first."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"measure","category":"Progress","title":"Measure consistently","summary":"Make comparisons meaningful by keeping the method stable.","image":"assets/education/education-measure.webp","sections":[["Record the context","Use the same unit and note the date. Where possible, keep the measurement conditions consistent and tell your coach when a method changes."],["Missing is not zero","Leave an unknown measurement blank. The portal keeps missing values separate from real readings and plots only values that were entered."],["Photographs","Use comparable pose, distance, lighting and clothing for private progress references. Uploaded photographs are saved privately in your coaching account."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','recovery','{"id":"recovery","category":"Recovery","title":"Recovery belongs in the conversation","summary":"Describe life outside the training plan.","image":"assets/education/education-recovery.webp","sections":[["Energy and sleep","Your check-in includes both hours of sleep and a quality rating. They describe different parts of the week and help provide context."],["Changing routines","Travel, work patterns and unusual fatigue can affect how manageable a plan feels. Share those changes rather than silently changing every target."],["Plan with your coach","Training and rest days are part of the assigned programme. Any change to frequency or intensity should be discussed through the coaching review."],["Look beyond a single tired day","One difficult session does not explain the whole programme. Look at the combination of sleep, work stress, soreness, appetite and repeated changes in performance. A week of unusual travel or long shifts is different from several weeks of growing fatigue under otherwise stable conditions.\n\nTell your coach which tasks feel affected and when the change began. “My usual warm-up felt unusually difficult on both lower-body days” gives clearer context than “recovery was bad”. Do not use wearable scores or a single rating as an automatic instruction to change the plan."],["Create a repeatable wind-down","Choose practical habits that fit your life: a more consistent bedtime, a manageable evening routine and a plan for late work or travel. The goal is a routine you can follow, not a perfect checklist that creates extra stress. Keep your agreed sleep and rest targets visible in the portal.\n\nDiscuss persistent fatigue, recurring discomfort or a meaningful drop in your capacity rather than repeatedly pushing through. Your coach can review training load and scheduling; symptoms that need medical assessment belong with a qualified healthcare professional."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"recovery","category":"Recovery","title":"Recovery belongs in the conversation","summary":"Describe life outside the training plan.","image":"assets/education/education-recovery.webp","sections":[["Energy and sleep","Your check-in includes both hours of sleep and a quality rating. They describe different parts of the week and help provide context."],["Changing routines","Travel, work patterns and unusual fatigue can affect how manageable a plan feels. Share those changes rather than silently changing every target."],["Plan with your coach","Training and rest days are part of the assigned programme. Any change to frequency or intensity should be discussed through the coaching review."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','shopping','{"id":"shopping","category":"Nutrition","title":"Prepare a useful shopping list","summary":"Turn your assigned meals into quantities you can check.","image":"assets/education/education-shopping.webp","sections":[["Choose a day variant","The grocery list uses the selected training, rest or higher-carb day. Repeating it across a week is a planning aid, not an automatic mixed-week menu."],["Check what you already have","Combined quantities keep each food’s reference unit. Review package sizes, fresh food storage and your schedule before buying."],["Simple preparation","Group meals with shared ingredients and note which quantities are raw or cooked. Keep oils, dressings and add-ons consistent with your plan."],["Build the list from your actual week","Select the day variant you plan to follow and check the number of times you will repeat it. If you use different variants, combine them deliberately instead of multiplying one training day by seven. The portal list groups the ingredients in the selected day; it does not assume a whole week of identical meals.\n\nCompare required quantities with what is already in the cupboard, then convert them into realistic package sizes. Check whether an amount is dry, cooked, drained or counted before shopping. Repeated ingredients from individually created recipe plans may need to be combined by name and preparation state."],["Prepare components, then assemble","Group practical tasks: wash vegetables, portion dry ingredients and plan which foods will be cooked fresh. Keep sauces and oils measured separately where the recipe requires them. Label prepared portions so a larger container does not become an uncertain serving size.\n\nFollow product storage directions and cool and refrigerate prepared food promptly. Cooking times in recipes are guides; use doneness checks and a food thermometer where specified. If your schedule changes, ask for a simpler recipe rather than preparing a complicated plan you cannot maintain."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"shopping","category":"Nutrition","title":"Prepare a useful shopping list","summary":"Turn your assigned meals into quantities you can check.","image":"assets/education/education-shopping.webp","sections":[["Choose a day variant","The grocery list uses the selected training, rest or higher-carb day. Repeating it across a week is a planning aid, not an automatic mixed-week menu."],["Check what you already have","Combined quantities keep each food’s reference unit. Review package sizes, fresh food storage and your schedule before buying."],["Simple preparation","Group meals with shared ingredients and note which quantities are raw or cooked. Keep oils, dressings and add-ons consistent with your plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','travel','{"id":"travel","category":"Lifestyle","title":"Eating out and travel","summary":"Take your plan into the real world.","image":"assets/education/education-travel.webp","sections":[["Plan ahead","Discuss regular restaurant meals, travel and food availability with your coach. Agree on flexible meal choices rather than guessing exact macros for every unfamiliar dish."],["Keep a short note","Describe the meal and the context in your nutrition feedback. Use an estimate only if your coach has asked for one."],["Return to your routine","A changed meal is useful information for the next adjustment. Review what was manageable and prepare the next planned meal."],["Use a flexible decision sequence","Begin with the choices you can see: an appropriate protein option, a carbohydrate portion, vegetables or fruit, and sauces or oils that are easy to identify. This helps you describe the meal and discuss adjustments without pretending to know an exact restaurant recipe. The sequence is a planning aid, not a universal serving prescription.\n\nWhen possible, review a menu before the event and decide what would fit the approach agreed with your coach. Ask about preparation and ingredients if allergies or dietary requirements matter. A menu photograph cannot confirm hidden ingredients."],["Return without compensation","After a changed meal, return to the next agreed meal and routine. Avoid inventing a punishment workout or an unplanned fast to compensate. Your feedback can be brief: what changed, how hungry or satisfied you felt and whether the same situation will happen again.\n\nFor longer travel, discuss the equipment, food access, time zone and number of realistic training opportunities in advance. A deliberate temporary plan gives the coach better information than several improvised changes made without context."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"travel","category":"Lifestyle","title":"Eating out and travel","summary":"Take your plan into the real world.","image":"assets/education/education-travel.webp","sections":[["Plan ahead","Discuss regular restaurant meals, travel and food availability with your coach. Agree on flexible meal choices rather than guessing exact macros for every unfamiliar dish."],["Keep a short note","Describe the meal and the context in your nutrition feedback. Use an estimate only if your coach has asked for one."],["Return to your routine","A changed meal is useful information for the next adjustment. Review what was manageable and prepare the next planned meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','guidelines','{"id":"guidelines","category":"Coaching","title":"Coaching guidelines","summary":"A clear working agreement for both sides.","image":"assets/education/education-guidelines.webp","sections":[["Your part","Keep profile information current, read your assigned plans, submit the agreed check-in and raise questions or problems promptly."],["Your coach’s part","Your coach sets targets, reviews feedback, approves exercise and food references, and publishes changes to your assigned plans."],["Support","Use the contact details your coach provides. This portal does not contain chat, payments, live training monitoring or video calls."],["Know what changes a plan","The coach publishes your training and nutrition assignments. Your check-in provides the context for the next decision, but it does not automatically change exercises or calorie targets. Read the current plan version after an update and ask which parts changed if that is unclear.\n\nRecipe templates, client recipe assignments and published meal plans are separate. Editing a template preserves the version already assigned to you until the coach reassigns it. Adding a recipe to your meal plan creates an individual plan copy, so another client’s meals are not changed by your adjustment."],["Keep the working relationship clear","Agree on the check-in day, the channel for questions and the usual response window directly with your coach. Use concise, specific messages and distinguish routine feedback from something that needs timely attention. The portal stores your coaching records; it is not an emergency response service.\n\nKeep account details private and review what information you include in photographs and written notes. Before changing device or replacing a local copy, save a backup. Where an online account is connected, check that the save completed before closing the page."]],"status":"published","version":2,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do update set data=excluded.data,revision=panda_records.revision+1,updated_at=now() where panda_records.revision=1 and panda_records.data='{"id":"guidelines","category":"Coaching","title":"Coaching guidelines","summary":"A clear working agreement for both sides.","image":"assets/education/education-guidelines.webp","sections":[["Your part","Keep profile information current, read your assigned plans, submit the agreed check-in and raise questions or problems promptly."],["Your coach’s part","Your coach sets targets, reviews feedback, approves exercise and food references, and publishes changes to your assigned plans."],["Support","Use the contact details your coach provides. This portal does not contain chat, payments, live training monitoring or video calls."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb;
insert into public.panda_records(kind,id,data) values('articles','strength-foundation','{"id":"strength-foundation","title":"Inside the Strength Foundation programme","title_ar":"داخل برنامج تأسيس القوة","summary":"Understand the push, pull, legs and upper-body structure already available in your portal.","summary_ar":"افهم تقسيم الدفع والسحب والساقين والجزء العلوي المتاح في بوابتك.","category":"Training knowledge","image":"","symbol":"workouts","related_program_id":"plan_strength","sections":[["The purpose of a split","A split organises training across the week. The Strength Foundation template separates pushing, pulling and lower-body work, then adds a balanced upper-body session. The labels describe where attention goes on each day; they are not a guarantee of a result. The useful programme is the one whose exercise choices, workload and schedule match the person using it.\n\nBodybuilding has long used split routines to distribute work across sessions. In this portal, the template gives the coach an editable starting structure rather than a rigid system every client must follow."],["How the template is organised","The default template contains Push on Monday, Pull on Tuesday, Legs on Thursday and Upper on Saturday. Push focuses on chest, shoulders and triceps; Pull on back and biceps; Legs on the lower body; Upper returns to chest, back and shoulders. Always check your assigned version because your coach can change these days and exercises.\n\nThe additional upper-body day changes the distribution of weekly work. Do not assume every muscle receives the same number of sets just because the plan has four sessions."],["What the structure can help with","A focused session makes preparation simpler: you can review a smaller group of movements and the equipment they require. Spreading work across the week can also make each session easier to schedule than placing everything into one day. These are organisational benefits, not evidence that one split is always superior.\n\nThe four-day commitment is also a constraint. If you repeatedly miss the same day, the programme you actually complete differs from the template. Tell your coach before trying to squeeze several sessions into a single catch-up workout."],["How to evaluate a useful week","Review whether you completed the agreed sessions, whether the prescribed movements remained controlled and whether the workload fitted your recovery. A good week does not require a personal best on every exercise. Clear technique, a repeatable setup and honest feedback make later comparisons more useful.\n\nTrack progression according to the method agreed with your coach. Avoid increasing load, sets and frequency simultaneously without a clear reason; it becomes harder to know what caused the change in how the plan feels."],["Use the guide with your assigned plan","Open Training to see your personal prescription, then use the exercise library for setup and technique cues. The template described here may have been adapted for your equipment, availability or limitations. If the coach has assigned a different programme, this guide is background knowledge and does not replace it.\n\nBring one specific question to your next check-in: which exercise, scheduling issue or recovery pattern would make the next week more manageable?"]],"sections_ar":[["هدف التقسيم","ينظم التقسيم التدريب خلال الأسبوع. يفصل قالب تأسيس القوة الدفع والسحب والجزء السفلي، ثم يضيف جلسة علوية متوازنة. تصف التسميات تركيز اليوم ولا تضمن نتيجة. يفيد البرنامج عندما تتناسب تمارينه وحمله وجدوله مع الشخص.\n\nتستخدم تدريبات بناء الأجسام التقسيم لتوزيع العمل. هنا يمنح القالب المدرب بداية قابلة للتعديل وليست نظاماً إلزامياً للجميع."],["تنظيم القالب","يحتوي القالب الافتراضي على الدفع يوم الاثنين والسحب الثلاثاء والساقين الخميس والجزء العلوي السبت. يركز الدفع على الصدر والأكتاف والترايسبس، والسحب على الظهر والبايسبس، والساقان على الجزء السفلي، والعلوي على الصدر والظهر والأكتاف. راجع نسختك المخصصة لأن المدرب يستطيع تغيير الأيام والتمارين.\n\nتغير الجلسة العلوية الإضافية توزيع العمل. لا تفترض تساوي مجموعات كل العضلات لمجرد وجود أربع جلسات."],["فوائد التنظيم","تسهل الجلسة المركزة التحضير بمراجعة مجموعة أصغر من الحركات والمعدات. وقد يسهل توزيع العمل جدولة الجلسات بدلاً من جمعها في يوم واحد. هذه فوائد تنظيمية وليست دليلاً على تفوق تقسيم واحد دائماً.\n\nالالتزام بأربعة أيام قيد أيضاً. تكرار تفويت يوم يغير البرنامج المنجز فعلياً. أخبر المدرب قبل ضغط عدة جلسات في تمرين تعويضي واحد."],["تقييم الأسبوع","راجع إكمال الجلسات والسيطرة على الحركات وتناسب الحمل مع التعافي. لا يتطلب الأسبوع الجيد رقماً شخصياً جديداً في كل تمرين. تجعل التقنية والإعداد الثابت والملاحظات الصادقة المقارنة مفيدة.\n\nتابع التقدم بالطريقة المتفق عليها. تجنب زيادة الوزن والمجموعات والتكرار الأسبوعي معاً دون سبب واضح، كي تفهم أثر التغيير."],["استخدم الدليل مع خطتك","افتح التدريب لرؤية وصفك الشخصي ومكتبة التمارين لإرشادات الإعداد. قد يعدل القالب حسب معداتك وتوفرك وحدودك. إذا خصص المدرب برنامجاً مختلفاً، فهذا الدليل معرفة عامة ولا يستبدله.\n\nقدم سؤالاً محدداً في المتابعة: أي تمرين أو مشكلة جدول أو نمط تعاف سيجعل الأسبوع التالي أسهل؟"]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','upper-lower','{"id":"upper-lower","title":"Upper / Lower: organise four purposeful sessions","title_ar":"العلوي والسفلي: تنظيم أربع جلسات هادفة","summary":"A practical guide to the four-day Upper / Lower template, its benefits and its trade-offs.","summary_ar":"دليل عملي لقالب العلوي والسفلي ذي الأربع جلسات وفوائده وحدوده.","category":"Training knowledge","image":"","symbol":"grid","related_program_id":"plan_build","sections":[["What upper / lower means","Upper / lower describes how sessions are divided by region of the body. Upper sessions usually combine pressing and pulling patterns; lower sessions organise knee-dominant and hip-dominant work with supporting exercises. It is a scheduling framework, not a special type of muscle contraction.\n\nLike other split routines, the idea is to distribute a useful amount of work across a week. The exact exercise list, effort, sets and rest periods matter more than the name on the programme."],["Read this portal’s actual template","The included template contains a balanced Upper session, a lower-body Legs session, a Push session and a Lower session with glute and hamstring focus. It is therefore an upper/lower-oriented template with a push emphasis on one upper day, not two identical upper sessions.\n\nThe default day labels are Monday for Push, Thursday for Legs, Friday for Lower and Saturday for Upper. The two lower-body days are consecutive in the starting template. The coach should review that spacing, exercise overlap and recovery before assigning it to an individual."],["Where the format can be useful","The separation makes it clear which movements belong to each session and gives the coach a straightforward way to adjust one part of the week. An upper session can be adapted to limited equipment without rebuilding every lower-body prescription. Similar movement patterns also make it easier to discuss a recurring setup problem.\n\nThis does not mean a four-day split is required for progress. Someone with fewer reliable training opportunities may need a different structure. The practical benefit disappears if the schedule is repeatedly impossible to complete."],["Balance effort across the week","A hard lower-body day can influence how the following day feels. Record relevant context and avoid assuming that different exercise names always mean completely different demands. Glute, hamstring and back work can overlap across movement patterns.\n\nAsk your coach how effort should vary between the sessions and how to handle a moved day. Reordering the week is sometimes useful, but the decision should preserve the intended balance rather than placing every demanding movement back to back."],["What to discuss at review","Compare the plan with your real availability, not an ideal calendar. Discuss session duration, equipment access, movement quality and recovery between the lower-body days. Your coach can change the days, exercise selection or programme itself while preserving your feedback history.\n\nThe right next step is a programme you can execute consistently and review meaningfully. Use the template as a shared starting point, then judge the assigned version by what it helps you do."]],"sections_ar":[["معنى العلوي والسفلي","يقسم هذا الأسلوب الجلسات حسب منطقة الجسم. تجمع الجلسات العلوية عادة الدفع والسحب، وتنظم السفلية العمل المتمحور حول الركبة والورك مع تمارين مساعدة. إنه إطار للجدولة وليس نوعاً خاصاً من الانقباض.\n\nالهدف توزيع العمل خلال الأسبوع. التمارين والجهد والمجموعات والراحة أهم من اسم البرنامج."],["اقرأ القالب الفعلي","يتضمن القالب جلسة علوية متوازنة وجلسة ساقين وجلسة دفع وجلسة سفلية تركز على الأرداف والخلفية. لذلك فهو قالب علوي وسفلي مع تركيز دفع في يوم علوي، وليس جلستين علويتين متطابقتين.\n\nالأيام الافتراضية هي الاثنين للدفع والخميس للساقين والجمعة للسفلي والسبت للعلوي. اليومان السفليان متتاليان في القالب الأولي؛ على المدرب مراجعة التباعد والتداخل والتعافي قبل التخصيص."],["متى يفيد","يوضح الفصل الحركات الخاصة بكل جلسة ويسهل تعديل جزء من الأسبوع. يمكن تكييف الجلسة العلوية للمعدات المتاحة دون إعادة بناء وصف الجزء السفلي. كما يسهل مناقشة مشكلة إعداد متكررة.\n\nلا يعني ذلك أن التقسيم لأربعة أيام شرط للتقدم. قد يحتاج من يتوفر له وقت أقل إلى تنظيم مختلف. تختفي الفائدة العملية إذا تعذر إكمال الجدول باستمرار."],["وازن الجهد","قد تؤثر جلسة سفلية شديدة على اليوم التالي. سجل السياق ولا تفترض أن اختلاف أسماء التمارين يعني اختلافاً كاملاً في المتطلبات؛ قد تتداخل عضلات الأرداف والخلفية والظهر.\n\nاسأل المدرب كيف يتوزع الجهد وكيف تتعامل مع نقل يوم. قد تفيد إعادة الترتيب بشرط الحفاظ على التوازن المقصود."],["ماذا تناقش","قارن الخطة بوقتك الحقيقي لا بجدول مثالي. ناقش مدة الجلسة والمعدات وجودة الحركة والتعافي بين اليومين السفليين. يستطيع المدرب تغيير الأيام أو التمارين أو البرنامج مع الحفاظ على تاريخ الملاحظات.\n\nالخطوة المناسبة برنامج تستطيع تنفيذه ومراجعته باستمرار. استخدم القالب نقطة بداية مشتركة وقيم النسخة المخصصة بما تساعدك على إنجازه."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','hit-hiit','{"id":"hit-hiit","title":"HIT and HIIT: two different ideas","title_ar":"HIT وHIIT: فكرتان مختلفتان","summary":"Understand high-effort strength training, interval conditioning and why the distinction matters.","summary_ar":"افهم تدريب القوة عالي الجهد واللياقة المتقطعة وأهمية التمييز بينهما.","category":"Training knowledge","image":"","symbol":"energy","related_program_id":"","sections":[["Start with the terms","HIT commonly means High Intensity Training in a strength-training context: a low-volume approach that places strong emphasis on effort during a small number of working sets. HIIT means High Intensity Interval Training: harder conditioning intervals alternated with recovery periods. The words look similar, but they describe different programming ideas.\n\nA difficult set of a resistance exercise is not automatically a HIIT workout. A timed circuit is not automatically the same as a low-volume strength programme. Ask what the session is intended to develop before copying its label."],["A short historical perspective","High-effort, low-volume strength training is associated with the Nautilus tradition and Arthur Jones. Its emphasis on brief, demanding work helped shape a continuing discussion about how much training is needed. Historical influence should not be confused with proof that a single method is best for everyone.\n\nA widely cited 1996 study by Izumi Tabata and colleagues examined very demanding intermittent cycle training and changes in aerobic and anaerobic capacity. It studied a specific protocol under controlled conditions. A general online “Tabata” circuit is not automatically equivalent to that experiment."],["Effort and volume are different variables","Effort describes how demanding a set is relative to what you can perform. Volume describes how much work is prescribed, commonly discussed through working sets and repetitions. Increasing effort does not make the amount of work irrelevant.\n\nIn one eight-week resistance-training trial in trained men, groups using different numbers of sets improved strength, while higher-volume conditions produced greater growth at several measured muscle sites. That finding does not prescribe your programme, but it is a useful reason to avoid the claim that the fewest possible sets always maximise muscle growth."],["Where intervals fit","Intervals organise conditioning into periods of work and recovery. The modality, effort, work duration, recovery duration and total repetitions all change the demand. Ten seconds of work on a bike and a minute of repeated jumps are not interchangeable because both are called intense.\n\nPossible benefits include a clearly structured session and a way to target conditioning within a limited time. The trade-off is that demanding intervals still require recovery and may affect the rest of your training week. More exhaustion is not the same as a better programme."],["Use the distinction in your coaching","The portal’s Strength Foundation and Upper / Lower templates are resistance-training structures; neither becomes a HIT or HIIT protocol simply by shortening rest. The Core & Activity Reference is also not labelled here as a validated interval protocol.\n\nIf you are interested in either approach, ask your coach how it would fit your goals, current ability, technique and recovery. Confirm the exact prescription instead of adding all-out intervals or failure sets on top of the existing plan. Stop an exercise you cannot control, and raise pain or unusual symptoms promptly."]],"sections_ar":[["ابدأ بالمصطلحات","يشير HIT في سياق القوة غالباً إلى أسلوب قليل الحجم يركز على جهد مرتفع في عدد صغير من مجموعات العمل. أما HIIT فهو فترات لياقة أشد تتناوب مع الراحة. تتشابه الكلمات لكن الفكرة مختلفة.\n\nالمجموعة الصعبة في المقاومة ليست تلقائياً HIIT، والدائرة المؤقتة ليست بالضرورة برنامج قوة قليل الحجم. اسأل عن هدف الجلسة قبل تقليد الاسم."],["لمحة تاريخية","يرتبط تدريب القوة عالي الجهد وقليل الحجم بتقليد نوتيلوس وآرثر جونز. ساهم التركيز على العمل القصير والشديد في النقاش حول مقدار التدريب المطلوب. التأثير التاريخي لا يثبت أن طريقة واحدة أفضل للجميع.\n\nدرست تجربة مشهورة لإيزومي تاباتا وزملائه عام ١٩٩٦ تدريب دراجات متقطعاً شديداً والتغيرات في القدرة الهوائية واللاهوائية. اختبرت بروتوكولاً محدداً تحت ظروف مضبوطة، ولا تعادله تلقائياً أي دائرة تاباتا على الإنترنت."],["الجهد والحجم مختلفان","يصف الجهد صعوبة المجموعة مقارنة بقدرتك، ويصف الحجم كمية العمل مثل مجموعات العمل والتكرارات. زيادة الجهد لا تلغي أهمية كمية العمل.\n\nفي تجربة مقاومة امتدت ثمانية أسابيع على رجال مدربين، تحسنت القوة مع أحجام مختلفة، بينما حققت بعض القياسات نمواً أكبر مع الحجم الأعلى. لا تحدد النتيجة برنامجك، لكنها سبب لتجنب ادعاء أن أقل عدد من المجموعات يعظم النمو دائماً."],["مكان الفترات","تنظم الفترات اللياقة إلى عمل وتعاف. تغير الأداة والجهد ومدة العمل والراحة وعدد التكرارات المتطلبات. عشر ثوان على الدراجة ودقيقة قفز متكرر ليستا بديلين لمجرد وصفهما بالشدة.\n\nمن الفوائد جلسة واضحة وتنظيم اللياقة ضمن وقت محدود. لكن الفترات الشديدة تحتاج تعافياً وقد تؤثر في الأسبوع التدريبي. الإرهاق الأكبر لا يعني برنامجاً أفضل."],["استخدم التمييز","قالبا تأسيس القوة والعلوي والسفلي في البوابة تنظيمان للمقاومة؛ تقصير الراحة لا يحولهما تلقائياً إلى HIT أو HIIT. كما لا يصنف مرجع الجذع والنشاط هنا كبروتوكول فترات مثبت.\n\nإذا رغبت في أحد الأسلوبين، ناقش ملاءمته لأهدافك وقدرتك وتقنيتك وتعافيك. حدد الوصف بدقة بدلاً من إضافة فترات قصوى أو مجموعات فشل فوق الخطة. أوقف التمرين غير المسيطر عليه وأبلغ عن الألم أو الأعراض غير المعتادة."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
commit;


-- Migration: 202609130005_featured_guides.sql
-- Add three original educational guides. Keep any existing coach-owned article.
begin;
insert into public.panda_records(kind,id,data) values ('articles','progressive-overload','{"id":"progressive-overload","category":"Training","title":"Progressive overload made simple","summary":"A practical way to recognise progress, choose the next step and keep technique consistent.","image":"assets/editorial/covers/progressive-overload.webp","sections":[["What progressive overload means","Progressive overload describes a gradual increase in the challenge of training as your capacity develops. It can involve more resistance, more repetitions at the same resistance, or another planned change to the work you perform. It is a principle for organising training, rather than a requirement to beat every previous session.\n\nStrength training works through repeated exposure and adaptation. A demanding session provides a stimulus; subsequent sessions give you opportunities to practise and develop. Your programme should leave room for that process. Adding weight without keeping the intended movement changes the task and makes comparison less useful."],["Keep the comparison fair","Before judging a set, check the exercise, equipment, range of motion, repetition count and rest. A machine stack marked 40 kg is not automatically equivalent to a different machine marked 40 kg. A dumbbell weight normally describes each dumbbell; confirm how your coach writes the load.\n\nUse the exercise guide to review the setup. Keep a short note when the bench angle, grip or equipment changes. A cleaner repetition or more reliable setup can be a useful improvement even when the load stays the same."],["An example: progress inside a rep range","Imagine an assigned exercise with three sets of 8–12 repetitions. This is an example, not an extra prescription. In one week you might perform 10, 9 and 8 controlled repetitions. At the same load, a later session of 11, 10 and 9 may show progress without a weight increase.\n\nOnce the top of the agreed range is repeatable with the intended technique and effort, discuss the next small load change with your coach. The repetition count may then move back towards the lower end. The aim is a repeatable progression, not a rushed jump."],["When a session feels harder","Sleep, unfamiliar equipment, a different training time and accumulated fatigue can change how the same prescription feels. One disappointing session is a reason to record context, not proof that the programme has failed. Do not compensate automatically with extra sets or an unplanned maximal attempt.\n\nIf performance declines repeatedly, bring the pattern to your check-in. Explain what changed, which exercises were affected and how recovery felt. Your coach can decide whether the appropriate response is more practice, a different progression or a temporary adjustment."],["Use it in your Panda plan","Open Training plans and read the selected day in full. The sets, repetition range, load guidance and rest belong together. Open each exercise for its setup and coaching cues before changing how you perform it.\n\nAt your next check-in, name one exercise and describe a useful comparison: the same setup, the same load, the repetitions achieved and how controlled the movement felt. The portal stores your check-in; it does not automatically infer a personal record from a planned load. Your coach publishes changes to the actual prescription."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
insert into public.panda_records(kind,id,data) values ('articles','protein-guide','{"id":"protein-guide","category":"Nutrition","title":"The practical guide to protein","summary":"Understand the daily target, choose useful foods and make protein fit your normal meals.","image":"assets/editorial/covers/protein-guide.webp","sections":[["Start with the daily picture","Dietary protein supplies amino acids used throughout the body, including in the repair and remodelling of muscle. Resistance training and adequate nutrition work together. A protein-rich snack cannot replace the training stimulus, and a hard session does not remove the need to eat regularly.\n\nFor many healthy exercising adults, research guidance places daily protein around 1.4–2.0 grams per kilogram of body mass. This is general context, not your personal target. Your coach’s assigned plan takes priority and may reflect goals, preferences and individual circumstances."],["Choose foods you can repeat","Chicken, fish, eggs, dairy foods, tofu, tempeh, beans and lentils can all contribute protein. Their portions, energy density, fibre and other nutrients differ. A useful choice is one that fits your preferences, budget, allergies and the rest of the meal.\n\nFor a plant-based routine, discuss a varied selection of protein foods with your coach. You do not have to make every food choice look like a bodybuilding menu. Familiar meals are often easier to shop for and prepare consistently."],["Food weight is not protein weight","A 150 g serving of chicken does not contain 150 g of protein. The portion is the food weight; the nutrient value is calculated from the food reference. Cooked and raw entries may differ because cooking changes water content and yield.\n\nIn Nutrition, open a meal and then an ingredient to see the reference portion and its nutrients. Follow the written preparation state. If a recipe uses dry rice or raw chicken, weighing the cooked food against those numbers will change the intended serving."],["Build a workable meal pattern","Instead of trying to fix the whole day at dinner, look at where protein foods already fit your meals. Breakfast might contain yogurt or eggs, lunch a chicken or lentil dish, and dinner fish or tofu. These are options to discuss, not an instruction to add all of them to your existing plan.\n\nA supplement is a convenience option when ordinary food is impractical. It is not automatically necessary. The total diet, portion sizes and tolerance matter more than collecting products. Ask your coach before replacing a planned meal with a shake."],["Read your targets without guesswork","The nutrition overview separates the nutrients in your planned meals from the targets set by your coach. A recipe card shows an estimate per serving, calculated from the listed ingredients. Its photograph illustrates presentation and cannot tell you the exact portion.\n\nIf you want an alternative, tell your coach which ingredient is difficult and why. Matching protein alone does not match calories, carbohydrate or fat. Your coach can assign a recipe, change the serving or publish an updated meal plan while keeping the overall strategy coherent."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
insert into public.panda_records(kind,id,data) values ('articles','consistency-guide','{"id":"consistency-guide","category":"Mindset","title":"Stay consistent when motivation fades","summary":"Build a routine with clear cues, realistic alternatives and a useful weekly review.","image":"assets/editorial/covers/consistency-guide.webp","sections":[["Make the decision smaller","Motivation changes from day to day. A repeatable routine reduces the number of decisions you need to make before starting. The practical question is not whether you feel inspired, but whether the next step is clear and manageable.\n\nPlanning is useful for some people, but writing a plan alone does not guarantee adherence. Work hours, caring responsibilities, access, energy and confidence all affect whether a routine is possible. A good coaching conversation takes those constraints seriously."],["Give the session a place in your day","Try describing the session as a concrete appointment: after work on Tuesday, go directly to the gym and open the assigned training day. Prepare the bag and the route beforehand if that removes a recurring obstacle. Keep the cue specific enough that you know when to act.\n\nChoose a schedule that fits the plan your coach assigned. Do not add sessions merely because an ideal week looks impressive on paper. A realistic four-day plan can become an unrealistic plan when each visit requires a long journey you have not accounted for."],["Agree on a fallback before you need it","Ask your coach what to do when work runs late, equipment is unavailable or you have less time than expected. A shorter approved session, a moved training day or a different exercise may be appropriate, depending on the programme. The fallback should be agreed rather than improvised from unrelated workouts.\n\nThe same idea applies to meals. Keep one practical alternative for a predictable busy day. Explain available ingredients and cooking facilities so the coach can make a useful substitution."],["Review patterns instead of judging yourself","In a weekly review, separate the event from the interpretation. “I missed Thursday because the meeting ended late” gives the coach something to work with. “I have no discipline” does not explain the obstacle or suggest a practical change.\n\nLook for repetition. If the same session moves every week, the schedule may need adjusting. If one meal is always difficult, its preparation or timing may be the problem. Change one useful thing and observe the next week before rebuilding the whole routine."],["Use the portal as a support system","Use Dashboard to find the next agreed action, Training for the current prescription and Recipes for practical meal preparation. Your check-in is where you connect these pieces with the reality of the week. Save a draft when a brief reflection is easier than completing everything at once.\n\nFinish the review with one achievable intention for the next week. It might be preparing your gym bag the evening before, confirming an exercise substitution or shopping for two planned meals. Consistency is built through repeatable actions and useful adjustments, not through an unbroken streak of perfect days."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
commit;


-- Migration: 202609140006_coaching_education.sql
-- TRAIN WITH PANDA 0.9.5 · coach tools and education content.
-- Additive migration. Existing plans, articles, foods and customer assignments stay intact.
begin;
create or replace function panda_private.validate_effort_program(p jsonb)
returns void language plpgsql set search_path='' as $$
declare d jsonb; x jsonb; scale text; target numeric;
begin
 if jsonb_typeof(p->'sessions') is distinct from 'array' then raise exception 'Invalid training sessions'; end if;
 for d in select value from jsonb_array_elements(p->'sessions') loop
  if jsonb_typeof(d->'exercises') is distinct from 'array' then raise exception 'Invalid training exercises'; end if;
  for x in select value from jsonb_array_elements(d->'exercises') loop
   scale:=coalesce(x->>'effort_scale','');
   if scale='' then
    if x ? 'effort_target' and x->'effort_target' not in ('null'::jsonb,'""'::jsonb) then raise exception 'Select RIR or RPE for an effort target'; end if;
   else
    if scale not in ('RIR','RPE') or jsonb_typeof(x->'effort_target') is distinct from 'number' then raise exception 'Invalid effort scale or target'; end if;
    target:=(x->>'effort_target')::numeric;
    if target < (case when scale='RPE' then 1 else 0 end) or target>10 or target*2<>trunc(target*2) then raise exception 'Effort target must be 0–10 RIR or 1–10 RPE, in half-point steps'; end if;
   end if;
  end loop;
 end loop;
end $$;
create or replace function panda_private.validate_coaching_update()
returns trigger language plpgsql set search_path='' as $$
declare x jsonb; f text; ds text; start_date date; end_date date;
begin
 if new.kind='programs' then perform panda_private.validate_effort_program(new.data);
 elsif new.kind='plan_history' and new.data->>'type'='programs' then
  if jsonb_typeof(new.data->'versions') is distinct from 'array' then raise exception 'Invalid plan history'; end if;
  for x in select value from jsonb_array_elements(new.data->'versions') loop perform panda_private.validate_effort_program(x->'snapshot');end loop;
 elsif new.kind='supplements' then
  if jsonb_typeof(new.data->'items') is distinct from 'array' or jsonb_array_length(new.data->'items')>40 then raise exception 'Use up to 40 supplement entries';end if;
  for x in select value from jsonb_array_elements(new.data->'items') loop
   if jsonb_typeof(x) is distinct from 'object' or coalesce(length(trim(x->>'name')),0)=0 then raise exception 'Give every supplement a name';end if;
   foreach f in array array['name','dose','timing','purpose','notes'] loop
    if x ? f and (jsonb_typeof(x->f) is distinct from 'string' or length(x->>f)>3000) then raise exception 'Invalid supplement text';end if;
   end loop;
   if x ? 'status' and (jsonb_typeof(x->'status') is distinct from 'string' or x->>'status' not in ('active','paused')) then raise exception 'Invalid supplement status';end if;
   start_date:=null;end_date:=null;
   foreach f in array array['start_date','end_date'] loop
    ds:=x->>f;
    if x ? f and jsonb_typeof(x->f) is distinct from 'string' then raise exception 'Invalid supplement date';end if;
    if coalesce(ds,'')<>'' then
     if ds !~ '^\d{4}-\d{2}-\d{2}$' or to_char(ds::date,'YYYY-MM-DD')<>ds then raise exception 'Invalid supplement date';end if;
     if f='start_date' then start_date:=ds::date;else end_date:=ds::date;end if;
    end if;
   end loop;
   if start_date>end_date then raise exception 'The end date must follow the start date';end if;
  end loop;
 elsif new.kind='clients' and new.data ? 'cardio_guidance' then
  if jsonb_typeof(new.data->'cardio_guidance') is distinct from 'string' or length(new.data->>'cardio_guidance')>3000 then raise exception 'Invalid cardio guidance';end if;
 elsif new.kind='foods' and new.data ? 'fiber' and new.data->'fiber'<>'null'::jsonb then
  if not panda_private.valid_number(new.data->'fiber',0,1000) then raise exception 'Fiber must be a non-negative number or unknown';end if;
 end if;
 return new;
end $$;
revoke all on function panda_private.validate_effort_program(jsonb),panda_private.validate_coaching_update() from public,anon,authenticated;
drop trigger if exists panda_coaching_update on public.panda_records;
create trigger panda_coaching_update before insert or update on public.panda_records for each row execute function panda_private.validate_coaching_update();
insert into public.panda_records(kind,id,data) select 'articles', value->>'id',value from jsonb_array_elements($panda095$[{"id":"hub-nutrition","category":"Nutrition Fundamentals","title":"Nutrition Fundamentals","summary":"Understand energy, nutrients and portions, then turn the numbers in your plan into meals you can repeat.","sections":[["Calories & energy balance","Calories describe energy. Over time, eating less energy than you use tends to reduce body weight; eating more tends to increase it. Daily readings are noisy, so one weigh-in cannot tell you whether a plan is working.\n\nUse the coach’s target as a starting point. Compare several weeks of intake, activity, hunger and measurements before changing it. A calculator estimates requirements; it does not measure your metabolism."],["Protein, carbs & fats","Protein supports the maintenance and repair of body tissues. Carbohydrate supplies energy for daily activity and training. Fat contributes to essential functions and makes meals satisfying. All three belong in the conversation; no single macro makes the whole diet good or bad.\n\nIn the app, targets and planned meal totals are separate. If they differ, ask whether the portion or the target should change instead of silently adding food."],["Fiber & micronutrients","Fiber comes from plant foods; vitamins and minerals support many normal body functions. The WHO advises at least 25 g of naturally occurring fiber daily for people older than ten. Individual needs and tolerance vary, so follow your assigned target and increase gradually.\n\nTry a practical food change, such as adding beans or replacing a refined grain with a whole grain. Unknown fiber values in the app mean the value needs checking, not that the food contains none."],["Portion control","A food entry is only useful if the portion unit matches what you eat. One scoop, one pack and 100 g are different references. Rice weighed dry is different from rice weighed cooked because the water content changes.\n\nFor a recipe, check how many servings the whole batch makes. Divide the finished dish into that number of portions, or adjust the servings in your assigned plan with your coach."],["Meal timing","Choose a meal pattern that fits your work, appetite and training. An elaborate schedule that you cannot maintain is less useful than a repeatable one. Before training, allow time to digest a meal you tolerate; very large meals immediately beforehand may feel uncomfortable.\n\nAfter training, return to your normal eating plan. You do not need to panic about missing a very narrow post-workout window. Discuss individual timing needs with your coach."],["Calorie deficit vs surplus","A deficit means less energy than estimated maintenance; a surplus means more. The size and duration should suit the goal, recovery and the person. Maintenance is also a valid phase, especially when building routines or managing a demanding schedule.\n\nDo not interpret a lower target as automatically better. Persistent exhaustion, poor training, dizziness or a difficult relationship with food are reasons to discuss the plan and seek appropriate support."],["How to read food labels","Start with the serving size and the number of servings in the package. Then compare energy, protein, carbohydrate, fat and fiber using the same reference amount. Front-of-pack words such as “protein” do not tell you the complete nutritional profile.\n\nLabels differ between countries in how carbohydrate and fiber are reported. Keep the label’s reference basis consistent when entering a food, and retain a note if the values are estimates."],["How to track calories and macros","Record the food, amount and preparation state. Include cooking oils, dressings and drinks when relevant. Use the same reliable entry repeatedly instead of selecting whichever result makes the numbers look best.\n\nTracking is a feedback tool, not a test of character. If precision creates anxiety, tell your coach and agree on a simpler method. Your next action: check the portion units in one full day of your assigned plan."]],"image":"assets/recipes/09.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"WHO · Healthy diet","url":"https://www.who.int/news-room/fact-sheets/detail/healthy-diet"},{"title":"ISSN · Protein and exercise","url":"https://link.springer.com/article/10.1186/s12970-017-0177-8"},{"title":"Mifflin et al. · Resting energy equation","url":"https://pubmed.ncbi.nlm.nih.gov/2305711/"}],"hub":"nutrition","icon":"nutrition"},{"id":"hub-swaps","category":"Food Swap Guide","title":"Food Swap Guide","summary":"Keep your plan flexible by understanding what a substitution matches—and what it changes.","sections":[["Protein swaps","Choose the nutrient you want to match before choosing the replacement. Chicken, fish, eggs, yogurt and tofu can contribute protein, but their fat, energy and serving sizes differ.\n\nFor example, a replacement with 20 g protein per 100 g needs 150 g to supply 30 g protein. That calculation matches protein only. Compare the rest of the meal before confirming the swap with your coach."],["Carb swaps","Rice, potatoes, pasta, bread and fruit can all contribute carbohydrate. Match the preparation state first: cooked rice cannot be compared gram-for-gram with dry pasta.\n\nIf your planned portion provides 40 g carbohydrate and the replacement provides 25 g per 100 g, the equivalent is 160 g. Then check fiber, energy and the practical portion. Use the app’s food details to confirm the numbers."],["Healthy fat swaps","Nuts, seeds, avocado and olive oil can fit into meals, but they are not interchangeable spoon-for-spoon. Nuts also contain protein and fiber; oil does not provide the same food structure.\n\nMeasure the portion you actually use. A free-poured dressing can differ considerably from a measured amount. Select the replacement because it fits the dish and your preferences, then adjust the quantity with your coach."],["Low-calorie alternatives","A useful alternative keeps the meal enjoyable while changing a part that contributes substantial energy. Examples include asking for dressing separately, using a smaller amount of oil, or replacing a sugary drink with water.\n\n“Low calorie” does not automatically mean more nutritious or more satisfying. Keep the main meal adequate. Avoid replacing meals with products simply because the label shows a small number."],["Vegetarian options","Consider tofu, tempeh, beans, lentils, dairy or eggs according to your preferences. Legumes usually contribute both carbohydrate and protein, so replacing meat with beans may also change the carbohydrate total.\n\nBuild a whole meal rather than trying to force every plant food into the same portion as meat. Tell your coach whether you avoid all animal products or only particular foods so the plan can be appropriate."],["The same macros with different foods","Matching three macro totals still does not match fiber, micronutrients, allergens, preparation time or fullness. Two meals can fit similar numbers while feeling very different.\n\nUse this order: identify the goal of the swap, check the label and unit, calculate the portion, compare the full meal, then save the agreed version. Your next action: agree on two reliable alternatives for the meal you most often miss."]],"image":"assets/recipes/18.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"swaps","icon":"nutrition"},{"id":"hub-eating-out","category":"Eating Out Guide","title":"Eating Out Guide","summary":"Make restaurant and social meals manageable without turning one imperfect meal into an abandoned week.","sections":[["Restaurant ordering","Read the menu before arriving when practical. Choose a main dish you enjoy, identify a protein source and consider a vegetable or other side that fits your plan. Ask about preparation if sauces, allergies or ingredients matter.\n\nRestaurant portions and oil use vary. An estimate is more honest than a false exact number. Share recurring restaurant meals with your coach so you can agree on a repeatable approach."],["Fast-food choices","Look for published nutrition information when available and check whether it describes the item alone or a full meal. Choose the portion deliberately; extras such as drinks, sauces and sides may change the total substantially.\n\nThere is no universal best order. Your budget, preferences and available options matter. Pick a workable meal and continue with your normal routine afterwards."],["Social meals","Decide what matters before the event: enjoying the food, seeing friends, or keeping a particular routine. You can do more than one without tracking every bite. Consider a normal meal earlier in the day rather than arriving extremely hungry.\n\nYou do not owe anyone an explanation for your choices. If asked, a simple “this works for me” is enough. Let your coach know about regular events."],["Buffets","Look at the options before filling your plate. Start with a meal-sized portion and sit down to eat it. You can return if you are still hungry; there is no need to sample everything at once.\n\nChoose favourites intentionally rather than collecting foods because they are available. If you track, describe the plate approximately. Do not invent precise gram amounts after the fact."],["Business dinners","Plan for uncertainty: timings may change, menus may be fixed, and the meal may last longer than expected. Bring a practical snack if the gap between meals will be large.\n\nAt dinner, make the choices available to you and focus on the conversation. A predictable breakfast and lunch can make the day easier without compensatory restriction. Record context for the weekly check-in if the schedule repeatedly disrupts your plan."],["When you cannot follow the diet","Return to your usual plan at the next suitable meal. Avoid punishment workouts, fasting to “erase” food or treating the week as ruined. One meal is a small part of a longer pattern.\n\nTell your coach what happened: availability, hunger, travel, cost or preference. That information improves the plan. Your next action: choose a simple fallback meal for days when the planned option is unavailable."]],"image":"assets/recipes/27.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"eating-out","icon":"nutrition"},{"id":"hub-shopping","category":"Grocery Shopping Guide","title":"Grocery Shopping Guide","summary":"Turn your assigned meals into a practical shopping list that fits your budget, kitchen and week.","sections":[["Protein shopping list","Start from the meals you will actually prepare. Depending on your preferences, options may include poultry, fish, eggs, yogurt, cottage cheese, tofu and pulses. Choose quantities for the number of planned servings.\n\nCheck storage life and freezer space. Buying a large pack is only economical if you can use it safely. Keep one convenient backup, such as an appropriate canned or frozen option."],["Carb shopping list","List the grains, bread, potatoes and fruit used in your plan. Check whether the recipe quantity is dry, cooked or drained before converting it into packs to buy.\n\nAvoid buying a different preparation simply because the package looks similar. Microwave rice, dry rice and a prepared rice dish may use different portion references. Save the product label if your coach needs to update the food entry."],["Healthy fats","Buy the portions you can use: nuts, seeds, olive oil and avocado are examples. A small bottle or pack may be more practical than a bulk purchase that goes unused.\n\nInclude cooking fats and dressings in the list. Measuring a portion once helps you understand the amount you usually use. It is an awareness exercise, not a requirement to make every meal laboratory precise."],["Fruits & vegetables","Choose a variety you enjoy and can realistically prepare. Fresh, frozen and suitable canned foods can all make the week easier. Separate produce for immediate meals from items that keep longer.\n\nA useful pattern is one ready-to-eat option, one frozen option and vegetables for your main recipes. Wash and prepare according to the food and store appropriately. Variety matters more than chasing one “superfood”."],["Meal-prep essentials","Before shopping, check containers, a kitchen scale if you use one, freezer bags and basic cooking equipment. Pick a preparation session that fits your calendar. You do not have to cook the entire week at once.\n\nLabel stored food with the preparation date and follow appropriate refrigeration, reheating and food-safety guidance. If storage conditions are uncertain, prepare a smaller batch."],["Budget-friendly foods","Compare unit prices and usable portions, not just the price on the front. Seasonal produce, frozen vegetables, oats and pulses can be practical options, depending on local prices.\n\nBuild the list from the app’s grocery view, check the cupboard first, and remove duplicates. Your next action: choose two main meals that share ingredients so your shopping produces fewer leftovers."]],"image":"assets/recipes/04.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"shopping","icon":"nutrition"},{"id":"hub-fat-loss","category":"Fat Loss Academy","title":"Fat Loss Academy","summary":"Understand trends, plateaus and maintenance so fat loss is guided by evidence rather than daily reactions.","sections":[["How fat loss actually works","A sustained energy deficit is the underlying driver of fat loss. Training, daily activity, food choices and routines influence whether that deficit is manageable. A single food, supplement or workout does not bypass the overall pattern.\n\nUse strength training and adequate nutrition as part of the plan, then review energy, hunger and performance alongside measurements. The aim is an approach you can carry out, not the largest possible deficit."],["Belly fat & spot reduction","You cannot reliably choose where fat is lost by training that body part. Abdominal exercises can develop the muscles and improve skill, but they do not selectively remove the fat covering them.\n\nAvoid judging progress by one area alone. Compare trends in body weight, measurements, photos and how clothing fits. Genetics and individual fat distribution affect which changes become visible first."],["How fast should weight change?","An appropriate rate depends on starting body size, health, training, previous dieting and the goal. There is no single weekly number that is right for everyone. Faster loss can make recovery and adequate eating harder.\n\nAgree on a range with your coach and review several weeks. If the process brings persistent dizziness, marked fatigue, menstrual changes or distress around food, pause and seek qualified assessment."],["Weight-loss plateaus","A plateau should be judged over a meaningful trend, not a few unchanged mornings. Check measurement consistency, meal portions, activity and adherence before assuming the body has stopped responding.\n\nBring a clear record to your coach: dates, average intake if tracked, steps and relevant changes. Adjust one factor at a time so you can learn what helped. Do not repeatedly cut food based on frustration."],["Why scale weight changes","Water, stored carbohydrate, food in the digestive system, sodium, menstrual changes and the timing of a weigh-in can move body weight without equivalent fat change. A salty meal can therefore affect the next morning’s reading.\n\nMeasure under similar conditions if weighing is useful for you. Treat the individual point as context and the longer pattern as the signal. The app preserves dated readings so you can compare fairly."],["Refeeds and diet breaks","A refeed or diet break is a planned period with changed intake, often closer to maintenance. It may make a long diet easier to manage, but it is not a guaranteed “metabolic reset” or a licence for uncontrolled eating.\n\nAgree on the purpose, duration and next review with your coach. Keep the same basic meal structure and use the break to observe recovery and hunger."],["Maintaining after fat loss","Maintenance needs a plan too. Discuss how intake, activity and monitoring will change after the deficit. Expect ordinary fluctuations rather than demanding that body weight remain on one exact number.\n\nKeep the routines that were useful: regular meals, strength training, practical shopping and honest check-ins. Your next action: agree on the signs that would trigger a review, rather than reacting to every small increase."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"fat-loss","icon":"flame"},{"id":"hub-muscle","category":"Muscle Building Academy","title":"Muscle Building Academy","summary":"Build a training process you can recover from, repeat and progressively improve.","sections":[["Progressive overload","Progressive overload means increasing the training challenge as capacity develops. It may involve more load, repetitions or appropriately planned work. Better control and a more consistent range of motion also improve the quality of comparison.\n\nUse the same exercise setup and follow the coach’s progression rule. Adding weight while shortening the movement changes the task and can make the training log misleading."],["Training volume","Volume describes how much training you perform. In practical coaching, challenging sets for a muscle group are one useful reference, but the quality of the sets and your recovery matter too.\n\nMore is not automatically better. If later sets lose the intended technique or interfere with the next session, discuss the workload. Record what you actually completed instead of copying the planned amount."],["Training frequency","Frequency is how often you train a movement or muscle group. Different schedules can work when the total work, exercise choice and recovery fit the person. Choose days you can attend consistently.\n\nIf work changes, ask your coach how to distribute the sessions. Do not squeeze every missed workout into consecutive days without considering fatigue and the next week’s plan."],["Exercise selection","Choose exercises that suit your equipment, goals, experience and movement tolerance. A familiar machine can be more useful than a complex lift you cannot set up reliably.\n\nUse the exercise library to confirm the intended variation, then keep it stable long enough to learn it. Report discomfort and equipment restrictions. A substitution should have a clear purpose rather than simply look more advanced."],["Muscle recovery","Training provides a stimulus; adaptation also requires recovery. Sleep, adequate food, sensible scheduling and the amount of other stress all affect how ready you feel. Soreness alone is not a score for workout quality.\n\nCompare performance, sleep and motivation across several sessions. Persistent decline is useful feedback for your coach. One tired day may call for an adjustment rather than abandoning the programme."],["Bulking vs lean gaining","A larger energy surplus does not guarantee a proportionally larger muscle gain. “Lean gaining” usually describes a more restrained approach with closer monitoring of weight, measurements and training.\n\nSelect an intake strategy with your coach. Review the direction of change alongside strength and recovery, then adjust gradually. The labels matter less than what the plan actually asks you to do each day."],["Natural muscle-building expectations","Muscle growth is gradual and varies with training experience, genetics, age, nutrition and consistency. Progress may be faster early in training and slower as experience increases. Social media images cannot establish what is realistic for your body.\n\nUse months of comparable records, not a single transformation photo. Your next action: choose one exercise and one routine you can improve consistently during the next training block."]],"image":"assets/editorial/covers/strength-foundation.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"muscle","icon":"workouts"},{"id":"hub-training","category":"Training Education","title":"Training Education","summary":"Decode the instructions in your workout: effort, repetitions, tempo, recovery and advanced methods.","sections":[["Warm-up & activation","Prepare for the specific session. Start with movement that raises your readiness, then use lighter practice sets of the first demanding exercises. An activation drill should help you perform the main work, not leave you exhausted before it.\n\nAsk your coach which warm-up sets are separate from working sets. Increase load gradually and use the warm-up to check equipment, range and how the movement feels today."],["Sets & reps","A repetition is one complete execution of the movement; a set is a group of repetitions before a rest. Three sets of 8–12 means a prescribed range for each working set, not 24–36 repetitions performed without a break.\n\nKeep the intended technique throughout. If the range is repeatedly too easy or impossible at the prescribed effort, report the actual load and repetitions to your coach."],["RPE & RIR","RIR means repetitions in reserve: the clean repetitions you estimate you could still complete at the end of a set. RPE means rating of perceived exertion. For resistance training, this app uses the RIR-based 1–10 RPE convention, not Borg’s 6–20 scale.\n\nNear the hard end, RPE 10 is approximately 0 RIR, RPE 9 about 1 RIR, RPE 8 about 2 RIR and RPE 7 about 3 RIR. These are estimates. Do not count repetitions that would require losing the agreed technique."],["Rest periods","Rest allows you to prepare for the next set. The assigned duration helps standardise the session and may differ between demanding lifts and smaller exercises.\n\nUse a timer when helpful, but also check that you are ready and the equipment is safe. If a short rest makes the prescribed work impossible, tell your coach. Shortening rest is not automatically an improvement."],["Tempo","Tempo describes the pace of parts of a repetition. Coaches may use words or a sequence of numbers for lowering, pauses and lifting. Ask which order your coach uses before interpreting a four-number prescription.\n\nUse the cue to control the movement rather than rush to finish the set. A slower tempo changes the task, so do not compare it directly with a faster version without noting the difference."],["Supersets","A superset pairs exercises with little or no rest between them, followed by the agreed recovery. It can help organise time, but the pairing influences fatigue and performance.\n\nCheck the exact order, whether the exercises use the same muscle groups, and where the rest belongs. Busy equipment may make a superset impractical; agree on a fallback rather than occupying several stations indefinitely."],["Dropsets","A dropset continues an exercise after reducing the load. It is an optional way to organise demanding work, not a requirement for progress.\n\nFollow the coach’s limits for the number of reductions and the stopping point. Do not add dropsets to every exercise because the session felt short. Extra fatigue may affect the rest of the programme."],["Training to failure","Failure is task-specific: you cannot complete another repetition under the agreed conditions. Technical breakdown and pain are reasons to stop; they are not targets to push through.\n\nTraining to failure is not necessary on every set. The choice depends on the exercise, safety setup, experience and programme. Use spotters or safety supports where appropriate and follow the assigned RIR or RPE."],["Deloads","A deload is a planned reduction in training stress, usually by adjusting load, volume or effort. It creates space to recover while maintaining useful practice.\n\nA deload does not mean you have failed or lost your progress. Confirm which variables change and when the normal plan resumes. Avoid adding unplanned extra work to compensate for the lighter schedule."],["Proper exercise technique","Use the library to understand the setup, movement and coaching cues, then apply the variation assigned to you. A photograph is a reference, not a personalised assessment of your technique.\n\nIf you are uncertain, ask for a coach review and describe what feels unclear. Your next action: identify the effort target and one technique cue before beginning your next working set."]],"image":"assets/editorial/covers/hit-hiit.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"Helms et al. · Repetitions in reserve and RPE","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4961270/"}],"hub":"training","icon":"workouts"},{"id":"hub-cardio","category":"Cardio & Conditioning","title":"Cardio & Conditioning","summary":"Use cardio and everyday movement to support fitness while keeping the whole training week manageable.","sections":[["Zone 2 cardio","“Zone 2” can mean different things in different heart-rate models. Do not assume that every watch or gym machine uses the same boundaries. Your coach should define the intended effort.\n\nFor a practical easy-to-moderate session, breathing is elevated but a conversation is still possible. Heat, fatigue and medication can affect heart rate. Use the agreed duration and effort rather than chasing a generic number."],["HIIT","High-intensity interval training alternates harder bouts with recovery. It differs from HIT strength-training approaches. The work duration, recovery and number of rounds determine the session, not simply feeling exhausted.\n\nHIIT is optional and should fit your experience and recovery. Start with the assigned format. Do not replace every easy cardio session with intervals just because the interval session is shorter."],["Steps & daily activity","Walking, household tasks and movement during work contribute to daily activity. Step counts can make a routine visible, but they are estimates and depend on the device.\n\nSet a realistic baseline before increasing a target. A short walk after a regular daily event can be easier to maintain than one large walk at an unpredictable time. Compare your own pattern using the same device."],["Cardio for fat loss","Cardio can contribute to energy expenditure and fitness, but exercise-machine calorie readings are estimates. Avoid automatically eating back every displayed calorie or using exercise as punishment for food.\n\nKeep the dietary plan and the activity plan coordinated with your coach. If extra cardio leaves you exhausted and less active for the rest of the day, the overall plan may need to change."],["Cardio vs resistance training","The two support different, overlapping aspects of fitness. Resistance training develops strength and muscle; aerobic activity develops cardiorespiratory capacity. Public-health guidance includes both aerobic and muscle-strengthening activity.\n\nThe balance should reflect your goal and schedule. If strength performance is a priority, discuss how demanding cardio sessions are placed around lower-body training."],["Increasing conditioning","Change one part of the plan at a time: duration, frequency or effort. A repeatable progression gives you better feedback than increasing all three simultaneously.\n\nRecord the activity type and how it felt, not only minutes. Walking uphill for twenty minutes and an easy cycle for twenty minutes are different sessions. Review recovery before making the next increase."],["Recovery between sessions","Plan easy days and recovery around harder work. Persistent breathlessness out of proportion to the activity, chest pain or faintness require stopping and appropriate medical assessment.\n\nFor ordinary fatigue, discuss a shorter or easier alternative with your coach. Your next action: check the activity target in your profile and agree on the effort and schedule that make those minutes meaningful."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"WHO · Physical activity","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity"}],"hub":"cardio","icon":"energy"},{"id":"hub-recovery","category":"Recovery & Lifestyle","title":"Recovery & Lifestyle","summary":"Recognise when to push, when to adjust and which everyday routines support your training.","sections":[["Sleep fundamentals","Treat sleep as part of the schedule. A reasonably consistent bedtime and wake time, a comfortable room and a wind-down routine can make it easier to settle. Adults generally need at least seven hours, with age and individual needs affecting the appropriate range.\n\nLook at repeated patterns rather than grading a single night. If sleep difficulties persist or you experience concerning daytime sleepiness, seek appropriate advice instead of relying on a supplement stack."],["Stress management","Work, family and training all place demands on your time and attention. Stress is not something you must eliminate before making progress. The aim is to keep the plan workable during demanding periods.\n\nChoose one small action: prepare tomorrow’s meal, take a short break or reduce a nonessential task. Describe major changes in your check-in so the coach can adjust expectations."],["Rest days","A rest day is part of the programme. It may include comfortable everyday movement, but it does not need an extra workout to “count”.\n\nUse the day for the practical things that support the next session: food preparation, equipment, sleep and scheduling. If you enjoy a walk, keep it appropriate to the recovery goal rather than turning every rest day into a competition."],["Hydration","Follow your assigned fluid guidance and discuss changes for heat, long sessions or heavy sweating. Requirements vary with conditions and the person; forcing large volumes is not automatically healthier.\n\nKeep fluid available and use your daily record to notice missed opportunities. If a clinician has advised fluid restriction or electrolyte management, that advice takes priority over a generic fitness target."],["Recovery signs","Useful signals include stable performance, manageable soreness, normal appetite and a routine you can maintain. No single wearable score or body sensation tells the whole story.\n\nCompare several signals over time. If performance and sleep are declining together, bring that pattern to your coach. A clear description of the change is more useful than simply marking yourself “unmotivated”."],["Managing fatigue","Separate expected tiredness after work from a pattern that persists or worsens. Consider recent changes in training, food, sleep and other demands.\n\nAvoid adding stimulants to conceal every sign of fatigue. Agree on a reduced session or recovery day when appropriate. New or unexplained symptoms deserve healthcare advice rather than a routine coaching adjustment."],["Training when tired","Use the warm-up to assess readiness. If the movement feels safe but the normal load is unusually difficult, the coach may have an option to reduce load, sets or effort.\n\nDo not chase a personal record to prove commitment. Your next action: agree on a minimum session and a clear stop rule before the next difficult week arrives."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"CDC · About sleep","url":"https://www.cdc.gov/sleep/about/index.html"}],"hub":"recovery","icon":"moon"},{"id":"hub-supplements","category":"Supplements HQ","title":"Supplements HQ","summary":"Understand optional supplements, recognise weak claims and use only the plan that has been reviewed for you.","sections":[["Which supplements are useful?","Start with a specific need. A supplement may fill a dietary gap or support a particular performance goal, but it does not replace training, food or sleep. More ingredients do not automatically produce a better result.\n\nYour coach’s assigned plan should identify the product, amount, timing and reason. A reference entry is educational; it is not an instruction for every client to take that product."],["Creatine","Creatine monohydrate can support repeated high-intensity efforts. It is optional, and an initial increase in scale weight may reflect water retention rather than fat gain.\n\nUse the amount agreed for your situation. Tell your healthcare professional about supplements if you have a medical condition, take medication or are being investigated for symptoms. Do not interpret a training guide as individual medical clearance."],["Protein powder","Protein powder is a convenient food supplement when ordinary meals make your protein target difficult to reach. It is not essential, and whey isolate is not automatically necessary for everyone.\n\nCheck the label, allergens, serving size and your tolerance. Count its nutrients in your meal plan. Taking extra protein on top of an already adequate intake does not guarantee extra muscle growth."],["Omega-3","Fish and other dietary sources can contribute omega-3 fats. A supplement decision should consider your diet and health context; it is not a universal recovery prescription.\n\nCheck EPA and DHA amounts rather than confusing total fish-oil weight with active fatty-acid content. Discuss use with a clinician or pharmacist if you take medication, especially medicines affecting blood clotting."],["Vitamin D","Vitamin D supports bone health and other normal functions. Supplementation should reflect diet, exposure, local guidance and, where appropriate, clinical assessment. It is not a guaranteed testosterone booster.\n\nK2 is not automatically mandatory whenever vitamin D is used. Avoid combining several products without checking their total vitamin content. Ask a qualified professional before using high-dose preparations."],["Multivitamins and ZMA","A multivitamin can help address specific intake gaps but cannot make a restrictive, poorly balanced diet complete. ZMA is a combination of minerals and vitamin B6; it should not be presented as a guaranteed sleep or hormone solution.\n\nCheck duplication with other products. “More than the daily requirement” is not necessarily a benefit. Address the dietary or sleep issue itself with suitable support."],["Caffeine and pre-workout","Caffeine can improve performance in some settings, but it can also disturb sleep or cause unpleasant effects. Natural and synthetic caffeine contain the same active molecule; “natural” does not guarantee a jitter-free experience.\n\nCount caffeine from coffee, energy drinks and supplements together. Avoid unmeasured pure caffeine and unclear blends. Dose and timing should reflect tolerance and health circumstances, not a stronger-is-better approach."],["When supplements are unnecessary","A product without a clear purpose adds expense and complexity. Amino-acid products may be unnecessary when protein intake is already adequate; many products marketed for fat burning or hormone optimisation make claims beyond their evidence.\n\nBefore adding something, ask: what problem does this solve, how will we judge its value, and what would make us stop? A simple plan is easier to follow and review."],["Supplement safety","Check the ingredient list, exact amounts, product quality and possible interactions. Independent batch testing can reduce some contamination risk but cannot guarantee that every product is appropriate or permitted in your sport.\n\nYohimbe/yohimbine can cause serious adverse effects and is not included as a routine fat-loss recommendation here. Ashwagandha also has important cautions, including reported liver injury and pregnancy concerns. Seek qualified advice before use; stop and obtain help if concerning symptoms occur."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"NIH ODS · Exercise and athletic performance","url":"https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/"},{"title":"NIH ODS · Omega-3","url":"https://ods.od.nih.gov/factsheets/Omega3FattyAcids-Consumer/"},{"title":"NIH ODS · Vitamin D","url":"https://ods.od.nih.gov/factsheets/VitaminD-Consumer/"},{"title":"NCCIH · Yohimbe","url":"https://www.nccih.nih.gov/health/yohimbe"},{"title":"NCCIH · Ashwagandha","url":"https://www.nccih.nih.gov/health/ashwagandha"},{"title":"ISSN · Creatine","url":"https://link.springer.com/article/10.1186/s12970-017-0173-z"},{"title":"ISSN · Protein and exercise","url":"https://link.springer.com/article/10.1186/s12970-017-0177-8"},{"title":"FDA · Caffeine","url":"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much"},{"title":"NIH · Vitamin K","url":"https://ods.od.nih.gov/factsheets/VitaminK-Consumer/"},{"title":"NIH · Weight-loss supplements","url":"https://ods.od.nih.gov/factsheets/WeightLoss-Consumer/"},{"title":"NCCIH · Berberine","url":"https://www.nccih.nih.gov/health/berberine-and-weight-loss-what-you-need-to-know"}],"hub":"supplements","icon":"water"},{"id":"hub-mindset","category":"Mindset & Consistency","title":"Mindset & Consistency","summary":"Build a routine that survives real life, missed sessions and ordinary changes in motivation.","sections":[["Consistency over perfection","Consistency is the pattern you return to, not an unbroken run of perfect days. A plan should have enough structure to guide you and enough flexibility to survive an unexpected day.\n\nMeasure success with actions you can repeat: preparing a meal, attending a session or sending an honest check-in. Do not let a missed target erase the useful work already completed."],["Motivation vs discipline","Motivation changes. A routine reduces how many decisions you need to make when motivation is low. Discipline can mean adjusting intelligently, not forcing the hardest option every time.\n\nPut the session in your calendar, prepare the equipment and agree on a smaller alternative. The easier it is to start, the less you need to rely on a particular mood."],["Building habits","Choose a small action, a reliable cue and a realistic setting. For example: after finishing work, put training clothes on before checking messages. Make the action specific enough that you know whether you did it.\n\nKeep the first version manageable. Review what interrupted it and change the environment or timing. Add complexity only when the basic routine is working."],["Handling missed workouts","Ask where the missed session fits in the remaining week. Sometimes moving it works; sometimes skipping it and continuing is more practical. Avoid doubling the workload without considering recovery.\n\nTell your coach whether the problem was time, access, fatigue or uncertainty. A repeated obstacle is a design problem in the routine, not evidence that you lack commitment."],["Handling “cheat meals”","Food does not need a moral label. A meal outside the plan is an event to understand, not a reason for punishment or a total restart.\n\nReturn to your normal routine and note the context if it is useful. If the plan repeatedly leads to feeling deprived or out of control, discuss that openly and seek qualified support where needed."],["Consistency while travelling","Choose a small set of anchors: a workable breakfast, daily movement and a realistic sleep opportunity. The travel version of your routine may be different from the home version.\n\nAsk for an equipment-limited workout in advance. Pack only what helps you follow the plan. A shorter, repeatable approach can preserve continuity without taking over the trip."],["Dealing with slow progress","Separate the outcome from the actions that influence it. Check whether the planned actions are happening and whether the measurements are comparable before deciding the plan has failed.\n\nUse a review date instead of evaluating yourself after every session. Your next action: choose one repeatable behaviour for the coming week and tell your coach how you will make it easier."]],"image":"assets/editorial/covers/checkin.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"mindset","icon":"target"},{"id":"hub-tracking","category":"Progress Tracking","title":"Progress Tracking","summary":"Collect comparable records and use them to make better coaching decisions.","sections":[["How to weigh yourself","If weighing is appropriate for you, use the same scale on a firm surface and similar conditions, such as after using the bathroom and before breakfast. Record the date and avoid switching methods repeatedly.\n\nA trend can be useful; daily weighing is not required for everyone. If it becomes distressing, discuss another monitoring approach. Weight is one signal among several."],["Taking progress photos","Use similar lighting, camera distance, pose and clothing so comparisons are meaningful. Choose a private setting and only take or share images you are comfortable storing.\n\nAvoid manipulating posture or lighting to force a result. Photos cannot precisely measure body-fat percentage. Record the date and compare changes over a reasonable interval rather than searching for daily differences."],["Body measurements","Agree on the location and technique for each measurement. Use the same tape position and similar tension. A slightly different measurement point can create an apparent change that is only a method difference.\n\nKeep notes if the method changes. If a value seems surprising, repeat the measurement calmly before saving it. Do not keep only the reading you prefer."],["Strength tracking","Compare the same exercise, equipment, range, repetitions and effort. A heavier load with fewer repetitions or different technique does not tell the same story as a like-for-like improvement.\n\nRecord actual work, including changes in rest or setup. RIR and RPE add context to the load. Share patterns across several sessions with your coach."],["Body-composition changes","Body weight can stay similar while strength, measurements or appearance change. Consumer body-composition devices provide estimates that may be affected by conditions such as hydration.\n\nAvoid treating one percentage reading as a precise diagnosis. Use several consistent measures and consider how you feel and perform. Your coach can help interpret the pattern within the limits of the available data."],["Weekly check-ins","A useful check-in includes what happened and why: sessions completed, food practicality, hunger, sleep, wins and obstacles. Give the coach enough context to make an informed adjustment.\n\nMention relevant changes in work, travel, health or medication. Do not edit the story to appear compliant. The purpose is to improve the next week, not to receive a score for the last one."],["Beyond the scale","Progress can include better exercise technique, more comfortable daily movement, a repeatable meal routine or improved confidence in using the gym. Choose indicators that relate to your actual goal.\n\nKeep them concrete: “completed three planned sessions” is easier to review than “was healthier”. Your next action: select one outcome measure and two daily or weekly actions to discuss in your next check-in."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"tracking","icon":"progress"},{"id":"hub-breathing","category":"Breathing & Performance","title":"Breathing & Performance","summary":"Use breathing cues to support controlled movement without turning them into rigid rules.","sections":[["Nasal breathing","Nasal breathing can be comfortable during rest and easier activity, but mouth breathing during hard exercise is a normal response to increased demand. Do not force one route if it makes the activity uncomfortable.\n\nUse breathing as an effort cue, not a test of toughness. Persistent or unusual breathing difficulty should be assessed by a qualified professional."],["Diaphragmatic breathing","Try quiet breathing in a comfortable seated or lying position. Let the lower ribs and abdomen move gently as you inhale, then exhale without forcing the air out. The goal is awareness, not the deepest possible breath.\n\nStop if you feel dizzy or uncomfortable. A brief practice may help you notice tension, but it is not a treatment for a medical breathing condition."],["Breathing during lifting","Coordinate breathing with the movement and the coach’s instructions. For many lighter exercises, exhaling through the demanding part and inhaling during the return is a useful starting cue.\n\nHeavy lifts can require different bracing strategies. Do not add prolonged breath-holding because you saw it online. Ask for individual instruction, especially if you have a condition affected by pressure changes."],["Bracing","Bracing means creating trunk tension to support the movement. It is not simply pulling the stomach inward. Your coach can help you find a repeatable setup for the load and exercise.\n\nPractise with an easy version before heavier work. A belt or a breathing cue does not replace learning the movement. Stop and reassess if the strategy produces pain or unusual symptoms."],["Breathing for cardio","Let breathing rise with effort. For an easier session, conversational breathing can help you stay near the intended intensity. Harder work will normally require a different pattern.\n\nAvoid treating a particular step-to-breath ratio as compulsory. Terrain, heat and fatigue change the demand. Follow the session purpose and slow down if the effort exceeds the plan."],["Recovery breathing","After a demanding effort, reduce activity gradually where appropriate and allow breathing to settle. A comfortable, unforced rhythm can be used during a short pause.\n\nDo not use hyperventilation or long breath holds as a routine recovery challenge. Your next action: ask your coach for one breathing and one bracing cue for the exercise you find hardest to control."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"breathing","icon":"energy"},{"id":"hub-mobility","category":"Mobility & Injury Prevention","title":"Mobility & Injury Prevention","summary":"Prepare joints and movements sensibly, recognise problems early and know when coaching is not enough.","sections":[["Basic mobility","Mobility is the ability to use a range of movement with control. The useful range depends on the task and the person; more range is not always necessary.\n\nChoose movements that support your programme and practise them comfortably. Avoid forcing yourself into a position to match a photograph. Mobility work does not guarantee freedom from injury."],["Joint preparation","Use the warm-up to practise the positions and loads that the session requires. Begin with manageable movement and build toward working sets rather than jumping straight to the heaviest load.\n\nYour coach may use a specific preparation drill where it helps. The drill should have a clear reason. Longer preparation is not automatically better if it adds fatigue without improving readiness."],["Movement quality","A useful movement is controlled, repeatable and appropriate to the goal and current tolerance. Bodies do not all look identical in the same exercise.\n\nCheck the equipment setup, balance and the agreed range. Ask for a review if you are unsure what to change. A small adjustment to load or setup may be more useful than collecting many conflicting online cues."],["Common training mistakes","Frequent problems include increasing workload too quickly, rushing the setup, changing technique to finish a set and adding extra intensity methods without a plan.\n\nUse the prescribed progression and record what you actually did. Keep the training area clear and check equipment before loading it. If instructions are unclear, ask before starting rather than guessing under load."],["When to reduce training","Discuss reducing load, effort or volume when fatigue is accumulating, technique becomes unreliable or discomfort appears. A coach can adjust a programme but should not diagnose an injury from an app entry.\n\nDo not use painkillers or stimulants simply to push through a new problem. Describe the location, timing and circumstances of symptoms so you can be directed to suitable help."],["When to seek qualified healthcare","Seek professional assessment for persistent or worsening pain, significant swelling, loss of function or recurring symptoms. Urgent symptoms such as chest pain, fainting or sudden severe breathing difficulty require prompt medical help.\n\nThe app is a training and education tool, not a diagnostic service. Your next action: agree with your coach how to report a problem and what would mean stopping a session."]],"image":"assets/editorial/covers/hit-hiit.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"mobility","icon":"workouts"},{"id":"hub-real-life","category":"Real-Life Fitness","title":"Real-Life Fitness","summary":"Make training and food work during travel, busy periods, social events and Ramadan.","sections":[["Fitness while travelling","Plan around the trip you will actually have. Check the timetable, food access and realistic opportunities for movement. Travel days may need simpler expectations than ordinary days.\n\nKeep a few routines that help: regular meals where possible, comfortable movement and a plan for the first day back. Tell your coach the dates before leaving so the programme can be adjusted."],["Hotel workouts","Check what equipment the hotel has before assuming a full gym is available. Ask your coach for a short session using suitable bodyweight, dumbbell or machine exercises.\n\nUse safe, stable equipment and enough space. Do not improvise heavy resistance with furniture or unsuitable fixtures. A short session with familiar movements can be more useful than an elaborate unfamiliar circuit."],["Busy work schedules","Choose realistic training windows and protect the most achievable ones. A smaller plan completed consistently is often more useful than a large plan repeatedly postponed.\n\nPrepare a fallback meal and an equipment-light session. If meetings regularly displace workouts, change the schedule rather than relying on extra willpower. Use the weekly check-in to explain the actual constraint."],["Limited equipment","Keep the goal of the exercise in mind when choosing an alternative. Range, resistance, stability and effort all matter. A band and a machine may work the same general area without being equivalent in load.\n\nAsk for approved substitutions and record the variation used. Do not compare kilograms directly across different equipment. Progress can also mean improved control or more repetitions under the agreed conditions."],["Ramadan fitness basics","Discuss the fasting schedule, sleep, hydration opportunities and training timing with your coach before Ramadan. Sessions closer to a time when food and fluids are available may be more practical, depending on your routine.\n\nAvoid aggressive dieting, dehydration or demanding sessions that you cannot recover from. Medical conditions, pregnancy or medication require individual healthcare advice. The plan should respect both your observance and your health."],["Social events","Decide what you want from the event and make a few practical choices in advance. You can enjoy a meal and still return to your normal routine afterwards.\n\nDo not try to “earn” food with exercise or skip necessary meals beforehand. Tell your coach when celebrations are frequent so the plan reflects your actual life rather than an imaginary perfect week."],["Staying fit on vacation","Maintenance can be a worthwhile vacation goal. Walking, enjoyable activity and a simple meal pattern may be enough to keep continuity without scheduling the whole trip around training.\n\nAgree on your priorities before leaving and how to restart afterwards. Your next action: write a three-part travel plan—movement, meals and the first session back—and share it with your coach."]],"image":"assets/editorial/covers/checkin.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"real-life","icon":"target"}]$panda095$::jsonb) on conflict(kind,id) do nothing;
