insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_everyday','{"id":"studio_nutrition_everyday","name":"Everyday Balanced Meals","name_ar":"وجبات يومية متوازنة","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"A varied omnivorous plan with four meals and two interchangeable menus.","description_ar":"خطة متنوعة تشمل مصادر حيوانية ونباتية مع أربع وجبات وقائمتين.","notes":"A varied omnivorous plan with four meals and two interchangeable menus. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"خطة متنوعة تشمل مصادر حيوانية ونباتية مع أربع وجبات وقائمتين. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":170.5,"carbs":215.3,"fat":65.6,"fiber":37.5,"calories":2134,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_1","name":"Blueberry protein overnight oats","name_ar":"شوفان ليلي بالتوت الأزرق","time":"07:30","instructions":"Stir the oats, yogurt, milk and chia in a jar until evenly combined.\n\nCover and refrigerate for at least 4 hours, or overnight.\n\nStir again and top with the washed blueberries before serving.","instructions_ar":"اخلط الشوفان والزبادي والحليب والشيا في وعاء.\n\nغطه وضعه في الثلاجة ٤ ساعات على الأقل أو طوال الليل.\n\nقلبه مرة أخرى وأضف التوت المغسول قبل التقديم.","items":[{"food_id":"ingredient_oats","quantity":62.5},{"food_id":"ingredient_yogurt","quantity":212.5},{"food_id":"ingredient_milk","quantity":100.0},{"food_id":"ingredient_blueberry","quantity":100.0},{"food_id":"ingredient_chia","quantity":12.5}],"image":"assets/recipes/01.webp","recipe_snapshot":{"id":"recipe_01","name":"Blueberry protein overnight oats","name_ar":"شوفان ليلي بالتوت الأزرق","category":"Breakfast","minutes":5,"wait_minutes":240,"servings":1,"summary":"A simple start, with clear portions and everyday ingredients.","summary_ar":"بداية بسيطة بمقادير واضحة ومكونات يومية.","ingredients":[{"id":"oats","name":"Rolled oats · dry","name_ar":"شوفان ملفوف · جاف","protein":13,"carbs":60,"fat":7,"fiber":10,"allergens":"Gluten","unit":"g","quantity":50},{"id":"yogurt","name":"Greek yogurt · plain, 0% fat","name_ar":"زبادي يوناني سادة خالي الدسم","protein":10,"carbs":4,"fat":0.4,"fiber":0,"allergens":"Milk","unit":"g","quantity":170},{"id":"milk","name":"Milk · 1.5% fat","name_ar":"حليب قليل الدسم","protein":3.5,"carbs":5,"fat":1.5,"fiber":0,"allergens":"Milk","unit":"g","quantity":80},{"id":"blueberry","name":"Blueberries · fresh","name_ar":"توت أزرق طازج","protein":0.7,"carbs":12,"fat":0.3,"fiber":2.4,"allergens":"","unit":"g","quantity":80},{"id":"chia","name":"Chia seeds","name_ar":"بذور الشيا","protein":17,"carbs":8,"fat":31,"fiber":34,"allergens":"","unit":"g","quantity":10}],"steps":["Stir the oats, yogurt, milk and chia in a jar until evenly combined.","Cover and refrigerate for at least 4 hours, or overnight.","Stir again and top with the washed blueberries before serving."],"steps_ar":["اخلط الشوفان والزبادي والحليب والشيا في وعاء.","غطه وضعه في الثلاجة ٤ ساعات على الأقل أو طوال الليل.","قلبه مرة أخرى وأضف التوت المغسول قبل التقديم."],"tags":["No-cook","Vegetarian"],"allergens":["Gluten","Milk"],"image":"assets/recipes/01.webp","status":"published","version":1,"notes":"Quantities refer to the ingredient state listed. Nutrition is estimated from ingredient references; brands and cooking yields vary. The photograph is a serving suggestion.","notes_ar":"الأوزان حسب حالة المكون الموضحة. القيم الغذائية تقديرية وتختلف باختلاف المنتجات والطهي. الصورة اقتراح للتقديم.","source":"Panda Kitchen · estimated ingredient values","created_at":"2026-09-13","updated_at":"2026-09-13"},"recipe_servings":1.25,"recipe_note":""},{"id":"meal_9","name":"Chicken rice and broccoli","name_ar":"دجاج مع الأرز والبروكلي","time":"12:30","instructions":"Cook the dry rice according to its packet. Cut the broccoli into florets.\n\nCoat the chicken with oil and spices. Pan-cook over medium heat, turning, until its centre reaches 74°C.\n\nSteam the broccoli until tender-crisp. Rest and slice the chicken, then serve with rice.","instructions_ar":"اطه الأرز الجاف وفق العبوة وقطع البروكلي إلى زهرات.\n\nغط الدجاج بالزيت والبهارات واطهه مع التقليب حتى تصل حرارته الداخلية إلى ٧٤°م.\n\nاطه البروكلي بالبخار ثم أرح الدجاج وقطعه وقدمه مع الأرز.","items":[{"food_id":"ingredient_chicken","quantity":225.0},{"food_id":"ingredient_rice","quantity":81.25},{"food_id":"ingredient_broccoli","quantity":225.0},{"food_id":"ingredient_oil","quantity":8.75},{"food_id":"ingredient_spice","quantity":2.5}],"image":"assets/recipes/09.webp","recipe_snapshot":{"id":"recipe_09","name":"Chicken rice and broccoli","name_ar":"دجاج مع الأرز والبروكلي","category":"Main meals","minutes":30,"wait_minutes":0,"servings":1,"summary":"A complete, practical plate for your weekly meal plan.","summary_ar":"وجبة متكاملة وعملية ضمن خطة طعامك الأسبوعية.","ingredients":[{"id":"chicken","name":"Chicken breast · raw, skinless","name_ar":"صدر دجاج نيئ دون الجلد","protein":23,"carbs":0,"fat":2,"fiber":0,"allergens":"","unit":"g","quantity":180},{"id":"rice","name":"Basmati rice · dry","name_ar":"أرز بسمتي جاف","protein":7.5,"carbs":78,"fat":0.7,"fiber":1.2,"allergens":"","unit":"g","quantity":65},{"id":"broccoli","name":"Broccoli · raw","name_ar":"بروكلي نيئ","protein":2.8,"carbs":4,"fat":0.4,"fiber":2.6,"allergens":"","unit":"g","quantity":180},{"id":"oil","name":"Olive oil","name_ar":"زيت زيتون","protein":0,"carbs":0,"fat":100,"fiber":0,"allergens":"","un