insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_vegetarian','{"id":"studio_nutrition_vegetarian","name":"Vegetarian Everyday Fuel","name_ar":"غذاء نباتي يومي","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"Meat-free meals using dairy, eggs, tofu and pulses; this is not a vegan plan.","description_ar":"وجبات دون لحوم تستخدم الألبان والبيض والتوفو والبقول؛ ليست خطة نباتية صرفة.","notes":"Meat-free meals using dairy, eggs, tofu and pulses; this is not a vegan plan. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"وجبات دون لحوم تستخدم الألبان والبيض والتوفو والبقول؛ ليست خطة نباتية صرفة. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":161.5,"carbs":243.6,"fat":77.5,"fiber":68.7,"calories":2318,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_2","name":"Banana oat protein pancakes","name_ar":"بان كيك الشوفان والموز","time":"07:30","instructions":"Blend the oats, half the banana and eggs to form a thick batter.\n\nBrush a non-stick pan with the measured oil. Cook small pancakes over medium-low heat for 2–3 minutes per side, until set.\n\nServe with the yogurt and remaining sliced banana.","instructions_ar":"اخلط الشوفان ونصف الموز والبيض للحصول على عجينة سميكة.\n\nادهن مقلاة غير لاصقة بالزيت المحدد واطه أقراصاً صغيرة ٢–٣ دقائق لكل جانب حتى تنضج.\n\nقدمها مع الزبادي وبقية شرائح الموز.","items":[{"food_id":"ingredient_oats","quantity"