insert into public.panda_records(kind,id,data) values('nutrition_plans','studio_nutrition_pescatarian','{"id":"studio_nutrition_pescatarian","name":"Pescatarian Meal Rotation","name_ar":"تنويع الوجبات مع الأسماك","status":"draft","version":1,"versions":[],"origin":"Panda Kitchen coach template · 2026-09-14","description":"Fish and seafood with eggs, dairy, grains and vegetables; no poultry or red meat.","description_ar":"أسماك ومأكولات بحرية مع البيض والألبان والحبوب والخضروات دون دواجن أو لحوم حمراء.","notes":"Fish and seafood with eggs, dairy, grains and vegetables; no poultry or red meat. Template portions and the 2.5 L fluid placeholder require individual review. Targets initially match Menu 1; Menu 2 has its own calculated totals. Check allergies, preparation state and product labels. Adjust servings, targets and timing before publishing. Recipe amounts are estimates, not a clinical prescription.","notes_ar":"أسماك ومأكولات بحرية مع البيض والألبان والحبوب والخضروات دون دواجن أو لحوم حمراء. تحتاج حصص القالب والقيمة الأولية للسوائل 2.5 لتر إلى مراجعة فردية. تطابق الأهداف القائمة الأولى مبدئياً، وللقائمة الثانية إجمالياتها المحسوبة. راجع الحساسية وحالة التحضير وملصقات المنتجات. عدّل الحصص والأهداف والتوقيت قبل النشر. الكميات تقديرية وليست وصفة سريرية.","targets":{"protein":175.9,"carbs":184.0,"fat":73.0,"fiber":31.9,"calories":2097,"water":2.5},"variants":[{"id":"day-1","name":"Menu 1","meals":[{"id":"meal_3","name":"Spinach feta omelette","name_ar":"أومليت السبانخ والفيتا","time":"07:30","instructions":"Wilt the spinach in the oil in a small non-stick pan. Beat the eggs and pour over the spinach.\n\nCook gently, add the feta and fold when the egg is fully set.\n\nToast the bread and serve with the omelette and tomatoes.","instructions_ar":"ذبّل السبانخ بالزيت في مقلاة صغيرة ثم أضف البيض المخفوق.\n\nاطه بهدوء وأضف الفيتا واطو الأومليت بعد نضج البيض تماماً.\n\nحمص الخبز وقدمه مع الأومليت والطماطم.","items":[{"food_id":"ingredient_egg","quantity":125.0},{"food_id":"