insert into public.panda_records(kind,id,data) values('supplement_templates','panda_supp_creatine','{"id":"panda_supp_creatine","name":"Creatine Essentials","name_ar":"أساسيات الكرياتين","summary":"A simple daily creatine routine for suitable strength clients.","summary_ar":"روتين كرياتين يومي بسيط لعملاء القوة المناسبين.","notes":"Adult coaching template. Review diet, product label, medical context and individual tolerance before assigning. Remove anything not needed; review at the next check-in.","notes_ar":"قالب تدريب للبالغين. راجع الطعام وملصق المنتج والحالة الصحية والتحمل الفردي قبل التخصيص. احذف ما لا يلزم وراجع الخطة في المتابعة القادمة.","status":"published","version":1,"items":[{"id":"panda_supp_creatine_creatine","name":"Creatine monohydrate","name_ar":"كرياتين مونوهيدرات","dose":"3 g daily","dose_ar":"٣ غ يومياً","timing":"Once daily, including rest days; with a meal if preferred.","timing_ar":"مرة يومياً، بما فيها أيام الراحة؛ مع وجبة إذا رغبت.","purpose":"Support repeated high-intensity training.","purpose_ar":"دعم التدريب المتكرر عالي الشدة.","notes":"No loading phase in this template. Review suitability if kidney disease, medicines or pregnancy/breastfeeding are relevant. Initial water-weight change is not fat gain.","notes_ar":"لا تتضمن هذه الخطة مرحلة تحميل. راجع الملاءمة عند وجود مرض كلوي أو أدوية أو حمل أو رضاعة. تغير الوزن الأولي بسبب الماء لا يعني زيادة الدهون.","status":"active","start_date":"","end_date":""}],"sources":["https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/"]}'::jsonb) on conflict(kind,id) do nothing;
