insert into public.panda_records(kind,id,data) values('supplement_templates','panda_supp_plant','{"id":"panda_supp_plant","name":"Plant-Based Strength","name_ar":"دعم القوة النباتي","summary":"Creatine and a plant-protein option for a plant-based routine.","summary_ar":"كرياتين وخيار بروتين نباتي لروتين يعتمد على النباتات.","notes":"Adult coaching template. Review diet, product label, medical context and individual tolerance before assigning. Remove anything not needed; review at the next check-in.","notes_ar":"قالب تدريب للبالغين. راجع الطعام وملصق المنتج والحالة الصحية والتحمل الفردي قبل التخصيص. احذف ما لا يلزم وراجع الخطة في المتابعة القادمة.","status":"published","version":1,"items":[{"id":"panda_supp_plant_creatine","name":"Creatine monohydrate","name_ar":"كرياتين مونوهيدرات","dose":"3 g daily","dose_ar":"٣ غ يومياً","timing":"Once daily, including rest days; with a meal if preferred.","timing_ar":"مرة يومياً، بما فيها أيام الراحة؛ مع وجبة إذا رغبت.","purpose":"Support repeated high-intensity training.","purpose_ar":"دعم التدريب المتكرر عالي الشدة.","notes":"No loading phase in this template. Review suitability if kidney disease, medicines or pregnancy/breastfeeding are relevant. Initial water-weight change is not fat gain.","notes_ar":"لا تتضمن هذه الخطة مرحلة تحميل. راجع الملاءمة عند وجود مرض كلوي أو أدوية أو حمل أو رضاعة. تغير الوزن الأولي بسبب الماء لا يعني زيادة الدهون.","status":"active","start_date":"","end_date":""},{"id":"panda_supp_plant_protein","name":"Plant protein · if needed","name_ar":"بروتين نباتي · عند الحاجة","dose":"A labelled serving providing 25 g protein; adjust to the remaining daily target.","dose_ar":"حصة بحسب الملصق توفر ٢٥ غ بروتين؛ عدّلها حسب المتبقي من الهدف اليومي.","timing":"Only on days food does not meet the protein target; at a convenient meal or after training.","timing_ar":"فقط في الأيام التي لا يحقق فيها الطعام هدف البروتين؛ مع وجبة مناسبة أو بعد التدريب.","purpose":"Fill a dietary protein gap.","purpose_ar":"سد نقص البروتين في الطعام.","notes":"Choose soy or a suitable pea/rice blend. Check the label for the portion providing 25 g protein and relevant allergens; include it in meal totals. Omit when food meets the target.","notes_ar":"اختر الصويا أو مزيج البازلاء والأرز المناسب. تحقق من الحصة التي توفر ٢٥ غ بروتين ومن مسببات الحساسية، واحسبها ضمن إجمالي الطعام. استغن عنه إذا حقق الطعام الهدف.","status":"active","start_date":"","end_date":""}],"sources":["https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('supplement_templates','panda_supp_training','{"id":"panda_supp_training","name":"Training-Day Focus","name_ar":"تركيز يوم التدريب","summary":"Optional low-dose caffeine and protein-gap support for suitable adults.","summary_ar":"كافيين اختياري بجرعة منخفضة ودعم احتياج البروتين للبالغين المناسبين.","notes":"Adult coaching template. Review diet, product label, medical context and individual tolerance before assigning. Remove anything not needed; review at the next check-in.","notes_ar":"قالب تدريب للبالغين. راجع الطعام وملصق المنتج والحالة الصحية والتحمل الفردي قبل التخصيص. احذف ما لا يلزم وراجع الخطة في المتابعة القادمة.","status":"published","version":1,"items":[{"id":"panda_supp_training_caffeine","name":"Caffeine · optional","name_ar":"كافيين · اختياري","dose":"100 mg from a clearly labelled serving; do not use bulk pure powder.","dose_ar":"١٠٠ ملغ من حصة محددة بوضوح على الملصق؛ لا تستخدم مسحوقاً نقياً سائبا.","timing":"On selected training days, 30–60 minutes before training; avoid near bedtime.","timing_ar":"في أيام تدريب مختارة، قبل التدريب بـ٣٠–٦٠ دقيقة؛ تجنبه قرب النوم.","purpose":"Optional alertness support after checking tolerance.","purpose_ar":"دعم اختياري لليقظة بعد التأكد من التحمل.","notes":"Healthy adults only. Count coffee, tea and energy drinks; keep total intake below 400 mg/day and single intake below 200 mg. Lower amounts can still disturb sleep. Omit with pregnancy/breastfeeding, stimulant sensitivity, relevant conditions or interacting medicines unless a qualified professional advises otherwise.","notes_ar":"للبالغين الأصحاء فقط. احسب القهوة والشاي ومشروبات الطاقة؛ اجعل الإجمالي أقل من ٤٠٠ ملغ يومياً والجرعة الواحدة أقل من ٢٠٠ ملغ. قد تؤثر كميات أقل في النوم. استغن عنه في الحمل والرضاعة أو حساسية المنبهات أو الحالات والأدوية ذات الصلة ما لم ينصح مختص مؤهل بخلاف ذلك.","status":"active","start_date":"","end_date":""},{"id":"panda_supp_training_protein","name":"Protein powder · if needed","name_ar":"مسحوق بروتين · عند الحاجة","dose":"A labelled serving providing 25 g protein; adjust to the remaining daily target.","dose_ar":"حصة بحسب الملصق توفر ٢٥ غ بروتين؛ عدّلها حسب المتبقي من الهدف اليومي.","timing":"Only on days food does not meet the protein target; at a convenient meal or after training.","timing_ar":"فقط في الأيام التي لا يحقق فيها الطعام هدف البروتين؛ مع وجبة مناسبة أو بعد التدريب.","purpose":"Fill a dietary protein gap.","purpose_ar":"سد نقص البروتين في الطعام.","notes":"25 g refers to protein, not powder weight. Count its calories and protein in the meal plan. Check milk/soy and other allergens. Omit when food meets the target.","notes_ar":"٢٥ غ تعني كمية البروتين، لا وزن المسحوق. احسب السعرات والبروتين ضمن خطة الطعام. تحقق من مسببات الحساسية مثل الحليب والصويا. استغن عنه إذا حقق الطعام الهدف.","status":"active","start_date":"","end_date":""}],"sources":["https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/","https://www.efsa.europa.eu/en/topics/topic/caffeine"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('supplement_templates','panda_supp_omega','{"id":"panda_supp_omega","name":"Low-Fish Nutrition Support","name_ar":"دعم التغذية قليلة الأسماك","summary":"A food-intake-led EPA/DHA option with clear label guidance.","summary_ar":"خيار EPA وDHA مبني على المدخول الغذائي مع إرشاد واضح للملصق.","notes":"Adult coaching template. Review diet, product label, medical context and individual tolerance before assigning. Remove anything not needed; review at the next check-in.","notes_ar":"قالب تدريب للبالغين. راجع الطعام وملصق المنتج والحالة الصحية والتحمل الفردي قبل التخصيص. احذف ما لا يلزم وراجع الخطة في المتابعة القادمة.","status":"published","version":1,"items":[{"id":"panda_supp_omega_omega","name":"Omega-3 · if dietary intake is low","name_ar":"أوميغا ٣ · عند انخفاض المدخول الغذائي","dose":"Labelled portion providing 250 mg combined EPA + DHA; adjust after reviewing food intake.","dose_ar":"حصة بحسب الملصق توفر ٢٥٠ ملغ من EPA وDHA معاً؛ عدّلها بعد مراجعة الطعام.","timing":"With a meal on days the reviewed diet does not provide enough EPA/DHA.","timing_ar":"مع وجبة في الأيام التي لا يوفر فيها الطعام المراجع ما يكفي من EPA وDHA.","purpose":"Complement a low-fish diet when appropriate.","purpose_ar":"استكمال نظام قليل الأسماك عند الملاءمة.","notes":"The 250 mg adult reference concerns total dietary intake, not an extra amount required for everyone. Check EPA+DHA rather than total fish-oil weight. Fish or algae products differ. Review allergies and anticoagulant use with a qualified professional. Not a high-dose triglyceride treatment.","notes_ar":"يشير مرجع ٢٥٠ ملغ للبالغين إلى إجمالي المدخول، وليس كمية إضافية لازمة للجميع. تحقق من EPA وDHA وليس وزن زيت السمك الكلي. تختلف منتجات السمك والطحالب. راجع الحساسية واستخدام مضادات التخثر مع مختص مؤهل. ليست علاجاً بجرعة عالية للدهون الثلاثية.","status":"active","start_date":"","end_date":""}],"sources":["https://www.efsa.europa.eu/en/efsajournal/pub/1461","https://ods.od.nih.gov/factsheets/Omega3FattyAcids-Consumer/"]}'::jsonb) on conflict(kind,id) do nothing;
commit;


