-- Migration: 202609290020_training_articles.sql
-- Training essentials, English and Arabic. Insert only; preserve all existing coach content.
begin;
insert into public.panda_records(kind,id,data) values ('articles','training-tempo','{"id":"training-tempo","category":"Training","title":"Tempo","summary":"Control each repetition, understand your programme and make your progress easier to measure.","image":"media/articles/01-tempo.png","sections":[["Every repetition has a rhythm","Two sets can use the same weight and repetition count yet feel very different. Lower a dumbbell with control, and you have time to maintain your position. Rush the lowering phase, bounce at the bottom and swing the weight back up, and you have changed the exercise. Tempo describes the timing of a repetition. It helps you understand how your coach wants you to perform the movement.\n\nThe aim is repeatable technique. You do not need to turn every set into a stopwatch test. Start by learning the movement, then use the prescribed rhythm to keep your repetitions consistent from the first to the last."],["How to read four-number tempo","A common tempo notation uses four characters: lowering, pause after lowering, lifting, and pause after lifting. For a squat, 3–1–1–0 means lower for approximately three seconds, pause for one second, stand up in approximately one second, then begin the next repetition without a deliberate pause at the top.\n\nThe order describes movement phases, not necessarily the first action of an exercise. A curl begins by lifting, although the first number still describes the lowering phase in this notation. If a prescription seems unclear, ask your coach to demonstrate one full repetition.\n\nAn X usually means lift with fast intent while maintaining control. It does not mean throw the weight, bounce, or abandon your position. A challenging weight may move slowly even when you are trying to lift it quickly. A zero means no deliberate pause; it does not mean skip that part of the movement."],["Control does not mean maximum slowness","Deliberately slowing a repetition can help you practise a position or follow a specific prescription. However, slower is not automatically better for muscle growth. A review comparing repetition durations found broadly similar growth across a range of timings; the evidence does not identify one magic tempo for everyone.\n\nWhen no tempo is written, ask your coach what they expect. A useful practical starting point is a controlled lowering phase, a smooth change of direction and a purposeful lift. Keep the range of motion and setup appropriate to the exercise. Avoid introducing long pauses or extremely slow repetitions simply to make a set feel harder."],["A practical example","Imagine your plan includes goblet squats for 8–10 repetitions at 3–1–1–0. Choose a load that lets you maintain the three-second descent and brief pause without collapsing your position. Count evenly in your head rather than watching a clock during the movement.\n\nIf repetition seven becomes a fast drop followed by a bounce, the set no longer matches the prescription. Stop when you cannot maintain the agreed technique, then discuss whether the next set needs less weight. Completing ten different-looking repetitions is less useful than knowing exactly how many matched your target."],["Compare like with like","Changing tempo changes the task. You may use less weight when a new programme adds a pause or lengthens the lowering phase. That does not automatically mean you have lost strength. Compare performances under similar conditions: the same exercise, equipment, range, rest and tempo.\n\nKeep notes simple: “Eight controlled reps; pause became difficult near the end.” This gives your coach more useful information than recording the load alone. The goal is to build a movement you can repeat and gradually progress."],["Before your next set","• Read the tempo alongside the repetition range and effort target.\n• Confirm what each character means for this exercise.\n• Choose a load that allows the prescribed movement.\n• Keep your rhythm without sacrificing position or breathing control.\n• Tell your coach when the tempo changes before the set is complete.\n\nTakeaway: Own the repetition before you increase the challenge. Tempo is a tool for clearer, more consistent training."]],"title_ar":"إيقاع التكرار","summary_ar":"تحكّم في كل تكرار، وافهم برنامجك، واجعل قياس تقدمك أسهل.","category_ar":"التدريب","sections_ar":[["لكل تكرار إيقاع","قد تستخدم مجموعتان الوزن نفسه وعدد التكرارات نفسه، لكن يختلف الإحساس بهما كثيراً. عندما تخفض الدمبل بتحكم، يتاح لك الحفاظ على وضعيتك. أما إذا أسرعت في النزول وارتددت في أسفل الحركة ثم أرجحت الوزن إلى أعلى، فقد غيّرت التمرين. يصف إيقاع التكرار توقيت مراحل الحركة، ويساعدك على فهم طريقة الأداء التي يريدها مدربك.\n\nالهدف هو تقنية يمكنك تكرارها بثبات. لا تحتاج إلى تحويل كل مجموعة إلى اختبار بساعة إيقاف. تعلّم الحركة أولاً، ثم استخدم الإيقاع المحدد لتبقى تكراراتك متسقة من البداية إلى النهاية."],["كيف تقرأ رموز الإيقاع الأربعة؟","تستخدم طريقة شائعة أربعة رموز بالترتيب: الخفض، والتوقف بعد الخفض، والرفع، والتوقف بعد الرفع. في القرفصاء، تعني ⁦3–1–1–0⁩ النزول خلال نحو ثلاث ثوانٍ، والتوقف ثانية واحدة، ثم الوقوف خلال نحو ثانية، وبدء التكرار التالي دون توقف مقصود في الأعلى.\n\nيصف هذا الترتيب مراحل الحركة، وليس بالضرورة أول حركة في التمرين. يبدأ تمرين ثني الذراع بالرفع، مع أن الرمز الأول يصف مرحلة الخفض في هذه الطريقة. إذا لم تكن الوصفة واضحة، اطلب من المدرب أن يريك تكراراً كاملاً.\n\nيعني الرمز X عادةً محاولة الرفع بسرعة مع الحفاظ على التحكم. لا يعني رمي الوزن أو الارتداد أو فقدان الوضعية. قد يتحرك الوزن الصعب ببطء رغم محاولتك رفعه بسرعة. ويعني الصفر عدم وجود توقف مقصود، وليس حذف جزء من الحركة."],["التحكم لا يعني البطء الشديد","قد يساعد إبطاء التكرار عمداً على التدرب على وضعية معينة أو اتباع وصفة محددة. لكن الأداء الأبطأ ليس أفضل تلقائياً لنمو العضلات. وجدت مراجعة قارنت مدد التكرار نمواً متقارباً عبر نطاق من الأزمنة، ولا تحدد الأدلة إيقاعاً سحرياً يناسب الجميع.\n\nإذا لم يُكتب إيقاع في خطتك، اسأل مدربك عما يتوقعه. يمكن البدء عملياً بخفض متحكم فيه، وتغيير سلس للاتجاه، ورفع مقصود. حافظ على مدى الحركة والإعداد المناسبين للتمرين. تجنب إضافة توقفات طويلة أو تكرارات بطيئة جداً لمجرد جعل المجموعة أصعب."],["مثال عملي","تخيل أن خطتك تتضمن قرفصاء الكأس من 8 إلى 10 تكرارات بإيقاع ⁦3–1–1–0⁩. اختر وزناً يسمح بالنزول ثلاث ثوانٍ والتوقف القصير دون فقدان وضعيتك. عدّ بإيقاع منتظم في ذهنك بدلاً من النظر إلى ساعة أثناء الحركة.\n\nإذا تحول التكرار السابع إلى هبوط سريع يتبعه ارتداد، لم تعد المجموعة تطابق الوصفة. توقف عندما تعجز عن الحفاظ على التقنية المتفق عليها، ثم ناقش ما إذا كانت المجموعة التالية تحتاج إلى وزن أخف. إنجاز عشرة تكرارات مختلفة في شكلها أقل فائدة من معرفة عدد التكرارات التي حققت الهدف فعلاً."],["قارن أداءً متشابهاً","تغيير الإيقاع يغيّر المهمة. قد تحتاج إلى وزن أخف عندما يضيف البرنامج توقفاً أو يطيل مرحلة الخفض. لا يعني ذلك تلقائياً أنك فقدت قوتك. قارن الأداء في ظروف متقاربة: التمرين والمعدات ومدى الحركة والراحة والإيقاع نفسها.\n\nاجعل ملاحظتك بسيطة، مثل: «ثمانية تكرارات متحكم فيها؛ أصبح التوقف صعباً في النهاية». يمنح ذلك مدربك معلومات أنفع من تسجيل الوزن وحده. الهدف هو بناء حركة تستطيع تكرارها والتقدم فيها تدريجياً."],["قبل مجموعتك التالية","• اقرأ الإيقاع مع نطاق التكرارات وهدف الجهد.\n• تأكد من معنى كل رمز في هذا التمرين.\n• اختر وزناً يسمح بالحركة المحددة.\n• حافظ على الإيقاع دون التضحية بالوضعية أو التحكم في التنفس.\n• أخبر مدربك إذا تغير الإيقاع قبل إتمام المجموعة.\n\nالخلاصة: أتقن التكرار قبل زيادة التحدي. الإيقاع أداة لتدريب أوضح وأكثر اتساقاً."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
insert into public.panda_records(kind,id,data) values ('articles','training-load-selection','{"id":"training-load-selection","category":"Training","title":"How Much Weight You Should Lift","summary":"Choose a load that matches your repetitions, technique and effort target—not the person training beside you.","image":"media/articles/02-how-much-weight.png","sections":[["Start with the prescription","The right weight is the weight that allows you to complete the intended task. Your exercise, repetition range, tempo and effort target all matter. A load suited to five repetitions may be inappropriate for fifteen. Even the same exercise can need a different load when your coach adds a pause or changes the range of motion.\n\nRead these details together before choosing a weight. If your plan says 8–12 repetitions with two repetitions in reserve, the target is a set inside that range while estimating that you could perform about two more repetitions with the same technique. Twelve repetitions completed by swinging or shortening the movement do not meet that target."],["Find your starting point","For an unfamiliar exercise, begin conservatively. Check the setup with a light practice set. On heavier exercises, build towards your working weight through progressively heavier warm-up sets, keeping them short enough that they do not become demanding working sets themselves.\n\nAfter adequate rest, use your first working set to assess the load. If you reach the top of the range and could clearly do many more clean repetitions than prescribed, a small increase may be appropriate. If you cannot reach the bottom of the range without losing technique or overshooting the effort target, reduce the load. You do not need a maximum-effort test to find a useful starting weight."],["Use a three-part check","Ask yourself: Did I reach the repetition range? Did I keep the intended movement? Did I finish near the prescribed effort? All three answers matter. A weight can be manageable for twelve repetitions but still too light for the intended stimulus. Another may feel challenging while forcing a shorter range from the very first repetition.\n\nFor example, your target is 8–12 reps with approximately two remaining. At ten reps, you estimate two more would be possible without changing technique. That is a reasonable match. If you reach eight and cannot complete another clean repetition, the weight is too demanding for that particular target, even though eight sits inside the written range."],["Progress in small steps","Your coach may use double progression: first improve repetitions within a range, then increase the load. Suppose three sets progress from 10, 9 and 8 repetitions towards 12, 12 and 12, while the intended effort and technique remain consistent. When that performance is repeatable, the next small weight increase may be appropriate. Your coach can specify when to make the change.\n\nThe new load may bring your repetitions back towards the lower end. If the available increment is too large, avoid forcing it. Ask about smaller plates, adjustable equipment, a different repetition target or staying at the current load longer. More weight is one way to progress; it is not a deadline for every workout."],["Keep the comparison fair","Machine labels are not interchangeable measurements of difficulty. Pulley arrangements, lever arms and seat positions change the exercise. Record the machine and setup when needed. For dumbbells, confirm whether your coach records each dumbbell or their combined weight; for barbells, confirm whether the bar is included.\n\nSleep, fatigue and exercise order can also affect today''s performance. Adjusting a load to meet the prescription is a useful training decision. Repeated difficulty across several sessions deserves a conversation about recovery and programming."],["Your load-selection checklist","• Check reps, tempo and effort before loading the equipment.\n• Warm up without exhausting yourself.\n• Judge the first working set using all three targets.\n• Use small, planned increases when performance supports them.\n• Record enough context for your coach to interpret the result.\n\nTakeaway: Choose the weight that makes the prescribed work challenging and repeatable. Let consistent performance earn the next increase."]],"title_ar":"ما الوزن المناسب الذي ينبغي أن ترفعه؟","summary_ar":"اختر وزناً يناسب تكراراتك وتقنيتك وهدف الجهد، لا وزن الشخص الذي يتدرب بجانبك.","category_ar":"التدريب","sections_ar":[["ابدأ بالوصفة التدريبية","الوزن المناسب هو الذي يسمح بإنجاز المهمة المطلوبة. نوع التمرين ونطاق التكرارات والإيقاع وهدف الجهد كلها عوامل مهمة. وزن يناسب خمسة تكرارات قد لا يناسب خمسة عشر. وحتى التمرين نفسه قد يحتاج إلى وزن مختلف إذا أضاف المدرب توقفاً أو غيّر مدى الحركة.\n\nاقرأ هذه التفاصيل معاً قبل اختيار الوزن. إذا كانت الخطة تطلب 8–12 تكراراً مع تكرارين احتياطيين، فالهدف إنهاء المجموعة ضمن هذا النطاق وأنت تقدّر أنك قادر على تكرارين إضافيين تقريباً بالتقنية نفسها. إنجاز اثني عشر تكراراً بالتأرجح أو تقصير الحركة لا يحقق هذا الهدف."],["حدد نقطة البداية","ابدأ بحذر عند تجربة تمرين غير مألوف. راجع الإعداد بمجموعة تدريبية خفيفة. في التمارين الأثقل، اقترب من وزن العمل عبر مجموعات إحماء بأوزان متزايدة، مع إبقائها قصيرة بما يكفي كي لا تصبح مجموعات عمل مرهقة بحد ذاتها.\n\nبعد راحة كافية، استخدم أول مجموعة عمل لتقييم الوزن. إذا بلغت أعلى نطاق التكرارات وكان بإمكانك بوضوح أداء تكرارات نظيفة أكثر بكثير مما تسمح به الوصفة، فقد تناسبك زيادة صغيرة. وإذا لم تبلغ الحد الأدنى دون فقدان التقنية أو تجاوز الجهد المحدد، فخفف الوزن. لا تحتاج إلى اختبار أقصى جهد لإيجاد وزن بداية مفيد."],["استخدم فحصاً من ثلاثة أسئلة","اسأل نفسك: هل بلغت نطاق التكرارات؟ هل حافظت على الحركة المطلوبة؟ هل انتهيت قريباً من الجهد المحدد؟ الإجابات الثلاث مهمة. قد تستطيع أداء اثني عشر تكراراً بوزن ما، لكنه يظل أخف من المطلوب للهدف. وقد يبدو وزن آخر صعباً لأنه يجبرك على تقصير الحركة منذ التكرار الأول.\n\nمثلاً، الهدف هو 8–12 تكراراً مع بقاء تكرارين تقريباً. عند التكرار العاشر تقدّر أنك تستطيع تكرارين آخرين دون تغيير التقنية؛ هذا تطابق معقول. أما إذا بلغت الثامن ولم تستطع تكراراً نظيفاً آخر، فالوزن أصعب من المطلوب لهذا الهدف تحديداً، رغم أن ثمانية تقع داخل النطاق المكتوب."],["تقدم بخطوات صغيرة","قد يستخدم مدربك التدرج المزدوج: تحسين عدد التكرارات ضمن نطاق أولاً، ثم زيادة الوزن. لنفترض أن ثلاث مجموعات تتقدم من 10 و9 و8 تكرارات نحو 12 و12 و12، مع ثبات الجهد والتقنية المطلوبين. عندما يصبح الأداء قابلاً للتكرار، قد تناسبك زيادة صغيرة في الوزن. يحدد مدربك متى تجري هذه الزيادة.\n\nقد يعيد الوزن الجديد عدد التكرارات نحو الحد الأدنى. إذا كانت الزيادة المتاحة كبيرة جداً، فلا تفرضها. اسأل عن أقراص أصغر أو معدات قابلة للضبط أو هدف تكرارات مختلف أو البقاء بالوزن الحالي مدة أطول. زيادة الوزن وسيلة للتقدم، وليست موعداً إلزامياً في كل حصة."],["حافظ على عدالة المقارنة","الأرقام المكتوبة على الأجهزة ليست مقاييس متكافئة للصعوبة. ترتيب البكرات وأذرع الرافعة وموضع المقعد تغيّر التمرين. سجل الجهاز وإعداده عند الحاجة. عند استخدام الدمبل، تأكد هل يسجل المدرب وزن كل دمبل أم الوزن الإجمالي؛ وعند استخدام البار، تأكد هل يشمل الرقم وزن البار نفسه.\n\nقد يؤثر النوم والتعب وترتيب التمارين في أدائك اليوم. تعديل الوزن لتحقيق الوصفة قرار تدريبي مفيد. أما تكرر الصعوبة عبر عدة جلسات فيستدعي مناقشة التعافي والبرنامج."],["قائمة اختيار الوزن","• راجع التكرارات والإيقاع والجهد قبل تحميل المعدات.\n• أحمِ جسمك دون إنهاكه.\n• قيّم أول مجموعة عمل وفق الأهداف الثلاثة.\n• استخدم زيادات صغيرة ومخططة عندما يدعمها الأداء.\n• سجل سياقاً كافياً ليساعد مدربك على تفسير النتيجة.\n\nالخلاصة: اختر الوزن الذي يجعل العمل المحدد صعباً وقابلاً للتكرار. دع الأداء المتسق يبرر الزيادة التالية."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
insert into public.panda_records(kind,id,data) values ('articles','training-effort','{"id":"training-effort","category":"Training","title":"How Hard You Should Train","summary":"Learn to judge effort so your sets are demanding, your technique stays useful and you can recover for the next session.","image":"media/articles/03-how-hard-to-train.png","sections":[["Hard enough for the task","A productive workout does not require every set to end in exhaustion. The appropriate effort depends on the exercise, your experience, the training goal and your current programme. A warm-up set, a technique practice set and a demanding muscle-building set have different purposes. Treating all three as maximum-effort tests makes the plan harder to follow.\n\nJudge a working set against its written target. Sweating, heavy breathing and muscle soreness do not tell you precisely how close your muscles were to their limit. A demanding squat set may leave you breathless; a curl can approach its limit without making you equally out of breath."],["Understand repetitions in reserve","Repetitions in reserve, or RIR, estimates how many additional repetitions you could complete with the same intended technique and range before reaching your limit. At 3 RIR, you believe around three remain. At 1 RIR, you believe one remains. At 0 RIR, no further complete repetition would be possible under those conditions.\n\nThe phrase “with the same technique” matters. If another repetition would require swinging, assistance or a substantially shorter range, do not count it as a clean repetition in reserve. Stop when you cannot maintain the agreed movement. You do not need to attempt a failed repetition to report an estimated 0 RIR."],["How RPE fits in","Some plans use a resistance-training rating of perceived exertion, or RPE, tied to RIR. On this particular scale, RPE 10 corresponds approximately to 0 RIR, RPE 9 to 1 RIR, RPE 8 to 2 RIR, and RPE 7 to 3 RIR. Other RPE scales describe overall exertion differently, so check which one your coach uses.\n\nThese are estimates, not exact measurements. Beginners often need time to judge remaining repetitions. Be honest about uncertainty: “Probably two or three left” is more useful than confidently guessing. Your coach can use your notes and, when appropriate, a technique video to help refine the estimate."],["Challenging does not always mean failure","Research suggests that training closer to failure can support muscle growth, but the exact best distance is uncertain and reaching failure on every set is not necessary. A practical coaching approach is often to leave a small number of clean repetitions available on many working sets, with the exact target chosen for the exercise and individual.\n\nFailure also has different consequences across exercises. Ending a machine curl is different from becoming stuck under a barbell. Follow your coach''s instructions and use appropriate safety arrangements. Avoid adding forced repetitions or unplanned failure attempts because a set did not feel dramatic enough."],["Put the target into practice","Imagine a seated row prescribed for 10–12 repetitions at 2 RIR. At repetition ten, you believe you could perform another four clean reps. Continue within the prescribed range. At twelve, if approximately two remain, you have matched the target. Stop there rather than turning the set into an unplanned endurance test.\n\nIf you reach your limit at nine, stop rather than force the tenth with a swinging torso. Note the result, take the planned rest and adjust the next set as agreed with your coach. If the same load becomes harder across sets, check your rest and accumulated fatigue instead of assuming you must reproduce the first set at any cost."],["Check the bigger picture","One difficult day is normal. Repeated performance drops, persistent fatigue or discomfort warrant feedback and a review of the plan. Sharp or unusual pain is a reason to stop the exercise, not evidence that you have reached the correct effort.\n\n• Read the effort target before the set.\n• Estimate only additional clean repetitions.\n• Keep rest periods consistent with your plan.\n• Record uncertainty and unexpected difficulty.\n• Share recurring recovery or technique problems with your coach.\n\nTakeaway: Train with intent, stop for a reason and leave enough capacity to keep progressing across the week."]],"title_ar":"ما مقدار الجهد الذي ينبغي أن تبذله في التدريب؟","summary_ar":"تعلم تقدير الجهد لتكون مجموعاتك فعالة، وتحافظ على تقنيتك، وتتعافى للجلسة التالية.","category_ar":"التدريب","sections_ar":[["جهد يناسب المهمة","لا تتطلب الحصة المفيدة إنهاء كل مجموعة بالإنهاك. يعتمد الجهد المناسب على التمرين وخبرتك والهدف وبرنامجك الحالي. لمجموعة الإحماء ومجموعة تعلم التقنية ومجموعة بناء العضلات الصعبة أغراض مختلفة. التعامل معها جميعاً كاختبارات لأقصى جهد يجعل اتباع الخطة أصعب.\n\nقيّم مجموعة العمل وفق هدفها المكتوب. التعرق وتسارع التنفس وألم العضلات اللاحق لا تخبرك بدقة بمدى اقتراب عضلاتك من حدها. قد تجعلك مجموعة قرفصاء صعبة تلهث، بينما قد يقترب ثني الذراع من حده دون أن يسبب الدرجة نفسها من ضيق النفس."],["افهم التكرارات الاحتياطية","التكرارات الاحتياطية، أو RIR، تقدير لعدد التكرارات الإضافية التي تستطيع إكمالها بالتقنية ومدى الحركة المطلوبين قبل بلوغ حدك. عند 3 RIR تعتقد أن لديك نحو ثلاثة تكرارات متبقية. وعند 1 RIR تعتقد أن لديك تكراراً واحداً. وعند 0 RIR لا يمكن إكمال تكرار آخر بالشروط نفسها.\n\nعبارة «بالتقنية نفسها» أساسية. إذا احتاج التكرار التالي إلى تأرجح أو مساعدة أو تقصير كبير لمدى الحركة، فلا تحسبه تكراراً نظيفاً احتياطياً. توقف عندما تعجز عن الحفاظ على الحركة المتفق عليها. لا يلزم أن تحاول تكراراً وتفشل فيه حتى تسجل تقديراً يبلغ 0 RIR."],["كيف يرتبط ذلك بمقياس RPE؟","تستخدم بعض الخطط مقياس الجهد المدرك RPE الخاص بتدريب المقاومة والمرتبط بالتكرارات الاحتياطية. في هذا المقياس تحديداً، يقابل RPE 10 تقريباً 0 RIR، وRPE 9 تكراراً احتياطياً واحداً، وRPE 8 تكرارين، وRPE 7 ثلاثة تكرارات. توجد مقاييس أخرى للجهد المدرك تصف الجهد العام بصورة مختلفة؛ لذا تأكد أي مقياس يستخدمه مدربك.\n\nهذه تقديرات وليست قياسات دقيقة. يحتاج المبتدئون غالباً إلى وقت لتقدير التكرارات المتبقية. عبّر بصدق عن عدم اليقين: «ربما بقي تكراران أو ثلاثة» أنفع من تخمين واثق. يمكن لمدربك استخدام ملاحظاتك، وفيديو للتقنية عند ملاءمته، لمساعدتك على تحسين التقدير."],["التحدي لا يعني دائماً الفشل العضلي","تشير الأبحاث إلى أن التدريب أقرب إلى الفشل العضلي قد يدعم نمو العضلات، لكن المسافة المثلى بدقة غير محسومة، وليس من الضروري بلوغ الفشل في كل مجموعة. من الأساليب التدريبية العملية ترك عدد قليل من التكرارات النظيفة في كثير من مجموعات العمل، مع اختيار الهدف الدقيق حسب التمرين والشخص.\n\nتختلف عواقب الفشل أيضاً بين التمارين. إنهاء مجموعة ثني الذراع على جهاز يختلف عن العجز عن رفع بار فوق جسمك. اتبع تعليمات مدربك واستخدم ترتيبات الأمان المناسبة. تجنب إضافة تكرارات بمساعدة أو محاولات فشل غير مخططة لمجرد أن المجموعة لم تبدُ شديدة بما يكفي."],["طبق الهدف عملياً","تخيل تمرين تجديف جالساً موصوفاً بـ10–12 تكراراً عند 2 RIR. عند التكرار العاشر تعتقد أنك قادر على أربعة تكرارات نظيفة أخرى. واصل ضمن النطاق المحدد. عند الثاني عشر، إذا بقي تكراران تقريباً، فقد حققت الهدف. توقف هناك بدلاً من تحويل المجموعة إلى اختبار تحمل غير مخطط.\n\nإذا بلغت حدك عند التاسع، فتوقف بدلاً من إجبار التكرار العاشر بأرجحة الجذع. سجل النتيجة، وخذ الراحة المحددة، وعدّل المجموعة التالية وفق اتفاقك مع المدرب. إذا أصبح الوزن نفسه أصعب عبر المجموعات، فراجع مدة الراحة والتعب المتراكم بدلاً من افتراض ضرورة تكرار أداء المجموعة الأولى بأي ثمن."],["انظر إلى الصورة الأشمل","من الطبيعي أن تمر بيوم صعب. أما الانخفاض المتكرر في الأداء أو التعب المستمر أو الانزعاج فتستدعي تقديم ملاحظات ومراجعة الخطة. الألم الحاد أو غير المعتاد سبب لإيقاف التمرين، وليس دليلاً على بلوغ الجهد المناسب.\n\n• اقرأ هدف الجهد قبل المجموعة.\n• قدّر التكرارات الإضافية النظيفة فقط.\n• اجعل فترات الراحة متسقة مع خطتك.\n• سجل عدم اليقين والصعوبة غير المتوقعة.\n• شارك مدربك مشكلات التعافي أو التقنية المتكررة.\n\nالخلاصة: تدرب بقصد، وتوقف لسبب واضح، واترك قدرة كافية لمواصلة التقدم خلال الأسبوع."]],"status":"published","version":1,"origin":"Panda Education","attachment":null}'::jsonb) on conflict (kind,id) do nothing;
commit;


-- Migration: 202611010021_client_access_expiry.sql
-- TRAIN WITH PANDA · Optional client access expiry.
-- Additive: access_expires_on is nullable and NULL means "no expiry", so every
-- existing account keeps exactly its current access. No rows are rewritten.
-- The date is the client's LAST day of access, compared in UTC everywhere.
begin;
alter table public.panda_accounts add column if not exists access_expires_on date;

-- One clock for every expiry comparison (RLS, RPCs, Edge Function): the UTC calendar date.
create or replace function panda_private.today() returns date language sql stable set search_path='' as $$
 select (now() at time zone 'utc')::date
$$;
revoke all on function panda_private.today() from public,anon;
grant execute on function panda_private.today() to authenticated;

-- RLS gate for every record, event and chat read and for every save: an expired
-- client's existing JWT stops working at the end of the last day, without a job.
create or replace function panda_private.ready() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.panda_accounts where user_id=auth.uid() and active and not must_change_password and to_timestamp(coalesce((auth.jwt()->>'iat')::bigint,0)) >= session_cutoff and (access_expires_on is null or access_expires_on >= panda_private.today()))
$$;

-- The coach edits the date on the client profile (panda_save / panda_register_client);
-- this keeps the enforced account column in step. Clients cannot change it: panda_save
-- already rejects any client edit outside their personal profile fields.
create or replace function panda_private.sync_client_access() returns trigger language plpgsql security definer set search_path='' as $$
declare v text; expires date;
begin
 if new.kind<>'clients' then return new; end if;
 if jsonb_typeof(new.data->'access_expires_on') not in ('string','null') then raise exception 'Choose a valid access expiry date.'; end if;
 v:=nullif(btrim(coalesce(new.data->>'access_expires_on','')),'');
 if v is not null then
  if v !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Choose a valid access expiry date.'; end if;
  begin expires:=v::date; exception when others then raise exception 'Choose a valid access expiry date.'; end;
  if to_char(expires,'YYYY-MM-DD')<>v or expires not between date '2000-01-01' and date '2100-12-31' then raise exception 'Choose a valid access expiry date.'; end if;
 end if;
 update public.panda_accounts set access_expires_on=expires where user_id=new.owner_id and role='client' and access_expires_on is distinct from expires;
 return new;
end $$;
revoke all on function panda_private.sync_client_access() from public,anon,authenticated;
drop trigger if exists panda_client_access_sync on public.panda_records;
create trigger panda_client_access_sync after insert or update on public.panda_records
for each row when (new.kind='clients') execute function panda_private.sync_client_access();

-- Why the signed-in account can or cannot use the portal, so sign-in can explain it.
-- Returns only the caller's own state and the coach's published contact details.
create or replace function public.panda_access_status() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a public.panda_accounts; profile_status text; brand jsonb; today date:=panda_private.today();
begin
 select * into a from public.panda_accounts where user_id=auth.uid();
 if a.user_id is null then return jsonb_build_object('state','inactive','today',today); end if;
 if a.role='client' then select r.data->>'status' into profile_status from public.panda_records r where r.kind='clients' and r.owner_id=a.user_id; end if;
 select r.data into brand from public.panda_records r where r.kind='settings' and r.id='brand';
 return jsonb_build_object(
  'state',case when not a.active then case when profile_status in ('paused','archived') then profile_status else 'inactive' end
               when a.access_expires_on is not null and a.access_expires_on<today then 'expired' else 'ok' end,
  'expires_on',a.access_expires_on,
  'days_left',a.access_expires_on-today,
  'today',today,
  'support',jsonb_strip_nulls(jsonb_build_object('coach',nullif(btrim(brand->>'coach'),''),'email',nullif(btrim(brand->>'email'),''),'phone',nullif(btrim(brand->>'phone'),''),'whatsapp',nullif(btrim(brand->>'whatsapp'),''),'hours',nullif(btrim(brand->>'hours'),''),'hours_ar',nullif(btrim(brand->>'hours_ar'),''))));
end $$;
revoke all on function public.panda_access_status() from public,anon;
grant execute on function public.panda_access_status() to authenticated;
commit;


-- Migration: 202611020022_client_timezone.sql
-- TRAIN WITH PANDA · Client access expiry in each client's own timezone.
-- access_expires_on stays the client's LAST day of access. Access now ends at 00:00 on the
-- following day in the client's timezone (021 used UTC). A client without a timezone uses the
-- installation default: settings/brand.default_timezone, else Asia/Colombo.
-- Additive and safe to re-run: two nullable columns, replaced functions, no rows rewritten.
begin;
alter table public.panda_accounts add column if not exists timezone text;
alter table public.panda_accounts add column if not exists country_code text;

-- IANA names only (Asia/Colombo, America/Argentina/Buenos_Aires, UTC), as known to this server.
create or replace function panda_private.valid_timezone(tz text) returns boolean language sql stable set search_path='' as $$
 select tz ~ '^(UTC|[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)+)$' and exists(select 1 from pg_catalog.pg_timezone_names where name=tz)
$$;
-- Validated when written (brand trigger below), so reading it in RLS stays a single lookup.
create or replace function panda_private.default_timezone() returns text language sql stable security definer set search_path='' as $$
 select coalesce((select nullif(btrim(r.data->>'default_timezone'),'') from public.panda_records r where r.kind='settings' and r.id='brand'),'Asia/Colombo')
$$;
-- The calendar date now in a timezone, and the instant access ends: 00:00 local on the day
-- after the expiry date. AT TIME ZONE applies that date's real offset, so DST is handled.
create or replace function panda_private.local_today(tz text, at timestamptz default now()) returns date language sql stable set search_path='' as $$
 select (at at time zone tz)::date
$$;
create or replace function panda_private.access_ends_at(expires date, tz text) returns timestamptz language sql stable set search_path='' as $$
 select (expires+1)::timestamp at time zone tz
$$;
revoke all on function panda_private.valid_timezone(text), panda_private.default_timezone(), panda_private.local_today(text,timestamptz), panda_private.access_ends_at(date,text) from public,anon;
grant execute on function panda_private.valid_timezone(text), panda_private.default_timezone(), panda_private.local_today(text,timestamptz), panda_private.access_ends_at(date,text) to authenticated;

-- Every writer of an account, the service role included, gets the same validation.
create or replace function panda_private.guard_account_timezone() returns trigger language plpgsql set search_path='' as $$
begin
 if new.timezone is not null and not panda_private.valid_timezone(new.timezone) then raise exception 'Choose a valid IANA timezone, for example Asia/Colombo.'; end if;
 if new.country_code is not null and new.country_code !~ '^[A-Z]{2}$' then raise exception 'Choose a valid country.'; end if;
 return new;
end $$;
revoke all on function panda_private.guard_account_timezone() from public,anon,authenticated;
drop trigger if exists panda_account_timezone_guard on public.panda_accounts;
create trigger panda_account_timezone_guard before insert or update of timezone, country_code on public.panda_accounts
for each row execute function panda_private.guard_account_timezone();

-- RLS gate: an already-issued session stops working at the client's local midnight.
create or replace function panda_private.ready() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.panda_accounts a where a.user_id=auth.uid() and a.active and not a.must_change_password and to_timestamp(coalesce((auth.jwt()->>'iat')::bigint,0)) >= a.session_cutoff and (a.access_expires_on is null or now() < panda_private.access_ends_at(a.access_expires_on,coalesce(a.timezone,panda_private.default_timezone()))))
$$;

-- The coach sets expiry, country and timezone on the client profile; this copies them to the
-- account that RLS reads. Clients cannot set them: panda_save refuses client edits outside their
-- personal fields, and this trigger refuses it again for any non-coach session.
create or replace function panda_private.sync_client_access() returns trigger language plpgsql security definer set search_path='' as $$
declare v text; expires date; tz text; cc text;
begin
 if new.kind='settings' then
  if new.id='brand' then
   if jsonb_typeof(new.data->'default_timezone') not in ('string','null') then raise exception 'Choose a valid IANA timezone, for example Asia/Colombo.'; end if;
   tz:=nullif(btrim(coalesce(new.data->>'default_timezone','')),'');
   if tz is not null and not panda_private.valid_timezone(tz) then raise exception 'Choose a valid IANA timezone, for example Asia/Colombo.'; end if;
  end if;
  return new;
 end if;
 if new.kind<>'clients' then return new; end if;
 if jsonb_typeof(new.data->'access_expires_on') not in ('string','null') then raise exception 'Choose a valid access expiry date.'; end if;
 v:=nullif(btrim(coalesce(new.data->>'access_expires_on','')),'');
 if v is not null then
  if v !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Choose a valid access expiry date.'; end if;
  begin expires:=v::date; exception when others then raise exception 'Choose a valid access expiry date.'; end;
  if to_char(expires,'YYYY-MM-DD')<>v or expires not between date '2000-01-01' and date '2100-12-31' then raise exception 'Choose a valid access expiry date.'; end if;
 end if;
 if jsonb_typeof(new.data->'timezone') not in ('string','null') then raise exception 'Choose a valid IANA timezone, for example Asia/Colombo.'; end if;
 if jsonb_typeof(new.data->'country') not in ('string','null') then raise exception 'Choose a valid country.'; end if;
 tz:=nullif(btrim(coalesce(new.data->>'timezone','')),'');
 cc:=nullif(btrim(coalesce(new.data->>'country','')),'');
 if tz is not null and not panda_private.valid_timezone(tz) then raise exception 'Choose a valid IANA timezone, for example Asia/Colombo.'; end if;
 if cc is not null and cc !~ '^[A-Z]{2}$' then raise exception 'Choose a valid country.'; end if;
 if tg_op='UPDATE' and auth.uid() is not null and not panda_private.coach() and (
  (old.data->>'access_expires_on') is distinct from (new.data->>'access_expires_on') or
  (old.data->>'timezone') is distinct from (new.data->>'timezone') or
  (old.data->>'country') is distinct from (new.data->>'country')) then
  raise exception 'Only your coach can change assignments and access' using errcode='42501';
 end if;
 update public.panda_accounts set access_expires_on=expires, timezone=tz, country_code=cc
 where user_id=new.owner_id and role='client' and (access_expires_on,timezone,country_code) is distinct from (expires,tz,cc);
 return new;
end $$;
revoke all on function panda_private.sync_client_access() from public,anon,authenticated;
drop trigger if exists panda_client_access_sync on public.panda_records;
create trigger panda_client_access_sync after insert or update on public.panda_records
for each row when (new.kind in ('clients','settings')) execute function panda_private.sync_client_access();

-- The caller's own access state, worked out in the caller's timezone.
create or replace function public.panda_access_status() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a public.panda_accounts; profile_status text; brand jsonb; tz text; today date; ends timestamptz;
begin
 select * into a from public.panda_accounts where user_id=auth.uid();
 if a.user_id is null then return jsonb_build_object('state','inactive'); end if;
 if a.role='client' then select r.data->>'status' into profile_status from public.panda_records r where r.kind='clients' and r.owner_id=a.user_id; end if;
 select r.data into brand from public.panda_records r where r.kind='settings' and r.id='brand';
 tz:=coalesce(a.timezone,panda_private.default_timezone());
 today:=panda_private.local_today(tz);
 if a.access_expires_on is not null then ends:=panda_private.access_ends_at(a.access_expires_on,tz); end if;
 return jsonb_build_object(
  'state',case when not a.active then case when profile_status in ('paused','archived') then profile_status else 'inactive' end
               when ends is not null and now()>=ends then 'expired' else 'ok' end,
  'expires_on',a.access_expires_on,
  'days_left',a.access_expires_on-today,
  'today',today,
  'timezone',tz,
  'timezone_source',case when a.timezone is null then 'default' else 'client' end,
  'ends_at',ends,
  'support',jsonb_strip_nulls(jsonb_build_object('coach',nullif(btrim(brand->>'coach'),''),'email',nullif(btrim(brand->>'email'),''),'phone',nullif(btrim(brand->>'phone'),''),'whatsapp',nullif(btrim(brand->>'whatsapp'),''),'hours',nullif(btrim(brand->>'hours'),''),'hours_ar',nullif(btrim(brand->>'hours_ar'),''))));
end $$;
revoke all on function public.panda_access_status() from public,anon;
grant execute on function public.panda_access_status() to authenticated;
commit;


-- Migration: 202611130023_client_intake.sql
-- TRAIN WITH PANDA · Client intake questionnaire: the client_intake record kind (INTAKE-DESIGN.md).
-- One record per client: id = owner_id = the client's auth uuid. The coach and the owning client can
-- read it; no package feature is required. A client writes it while onboarding (as a draft) or after
-- the coach reopens it; submitting locks it again. Validation, the write window and the
-- server-managed fields (submitted_at, submitted_profile, health_flag) live in a trigger.
-- panda_save and readable() are PATCHED in place, never re-created from a file: their installed
-- bodies carry migrations 009, 010 and 014, which no single file contains.
-- Additive and safe to re-run: no customer record is rewritten.
begin;

-- 1. Record kinds and ownership -----------------------------------------------------------------
-- Preflight: the current lists must be exactly the ones this migration expects (022), or already
-- include client_intake (re-run). Anything else means a kind was added elsewhere: stop.
do $migration$
declare def text; have text[];
 old_kinds constant text[]:=array['clients','client_private','packages','foods','programs','nutrition_plans','checkins','checkin_private','measurements','activity','photos','articles','invoices','drafts','settings','plan_history','supplements','recipes','recipe_assignments','recipe_images','supplement_templates','supplement_references'];
 old_owned constant text[]:=array['clients','client_private','checkins','checkin_private','measurements','activity','photos','invoices','drafts','supplements','recipe_assignments'];
begin
 select pg_get_constraintdef(c.oid) into def from pg_constraint c where c.conrelid='public.panda_records'::regclass and c.conname='panda_records_kind_check';
 if def is null then raise exception 'panda_records_kind_check not found; review migration 023'; end if;
 select array_agg(m.r[1] order by m.r[1]) into have from regexp_matches(def,'''([a-z_]+)''','g') as m(r);
 if have=(select array_agg(x order by x) from unnest(old_kinds||'client_intake'::text) x) then null;
 elsif have=(select array_agg(x order by x) from unnest(old_kinds) x) then
  alter table public.panda_records drop constraint panda_records_kind_check;
  alter table public.panda_records add constraint panda_records_kind_check check (kind in ('clients','client_private','packages','foods','programs','nutrition_plans','checkins','checkin_private','measurements','activity','photos','articles','invoices','drafts','settings','plan_history','supplements','recipes','recipe_assignments','recipe_images','supplement_templates','supplement_references','client_intake'));
 else raise exception 'Unexpected record kinds in panda_records_kind_check: %; review migration 023',def;
 end if;

 select pg_get_constraintdef(c.oid) into def from pg_constraint c where c.conrelid='public.panda_records'::regclass and c.conname='panda_records_ownership_check';
 if def is null then raise exception 'panda_records_ownership_check not found; review migration 023'; end if;
